  function getBootSubNavSection() {
    return String(document.documentElement.getAttribute("data-sa-boot-section") || "").trim();
  }

  function getSubNavKeyForSection(section) {
    const nextSection = String(section || "").trim();
    if (nextSection === "payment-partners" || nextSection === "delivery-partners" || nextSection === "ai-integration") {
      return "services";
    }
    if (nextSection === "seller-feedback" || nextSection === "user-feedback") {
      return "feedback";
    }
    return nextSection;
  }

  function hasBootSubNavSkeleton() {
    return document.documentElement.classList.contains("sa-boot-subnav-skeleton");
  }

  function clearBootSubNavSkeleton(section) {
    if (!hasBootSubNavSkeleton()) {
      return;
    }
    const bootSection = getBootSubNavSection();
    const requested = String(section || "").trim();
    if (requested && bootSection && requested !== bootSection) {
      return;
    }
    document.documentElement.classList.remove("sa-boot-subnav-skeleton");
    document.documentElement.removeAttribute("data-sa-boot-section");
  }

  function readSubNavSkeletonCount(key, fallback = 6) {
    const safeFallback = Math.max(3, Math.min(12, Number(fallback) || 6));
    try {
      const cache = JSON.parse(window.localStorage.getItem(subNavSkeletonCountStorageKey) || "{}") || {};
      const count = Math.trunc(Number(cache[key]));
      return Number.isFinite(count) && count > 0 ? Math.min(12, Math.max(3, count)) : safeFallback;
    } catch (error) {
      return safeFallback;
    }
  }

  function cacheSubNavSkeletonCount(key, count) {
    try {
      const cache = JSON.parse(window.localStorage.getItem(subNavSkeletonCountStorageKey) || "{}") || {};
      cache[key] = Math.max(0, Math.trunc(Number(count)) || 0);
      window.localStorage.setItem(subNavSkeletonCountStorageKey, JSON.stringify(cache));
    } catch (error) {
      // Ignore storage failures; subnav skeletons can still fall back to 6 rows.
    }
  }

  function paintSubNavSkeleton(host, count = 6) {
    if (!(host instanceof HTMLElement)) {
      return;
    }
    const safeCount = Math.max(3, Math.min(12, Number(count) || 6));
    const existing = host.querySelectorAll(":scope > .sa-subnav-skeleton");
    if (existing.length === safeCount && existing.length === host.children.length) {
      host.classList.add("is-skeleton-loading");
      syncSidebarSubNavExpandedHeight(host);
      return;
    }
    host.replaceChildren();
    host.classList.add("is-skeleton-loading");
    for (let index = 0; index < safeCount; index += 1) {
      const row = document.createElement("span");
      row.className = "super-admin-company-status-nav__item sa-subnav-skeleton";
      row.setAttribute("aria-hidden", "true");
      const line = document.createElement("span");
      line.className = "sa-subnav-skeleton__line";
      row.append(line);
      host.append(row);
    }
    syncSidebarSubNavExpandedHeight(host);
  }

