  function normalizePlatformSettings(source) {
    const normalized = { ...platformSettingDefaults };
    if (!source || typeof source !== "object") {
      return normalized;
    }
    for (const key of Object.keys(platformSettingDefaults)) {
      if (!Object.prototype.hasOwnProperty.call(source, key)) {
        continue;
      }
      if (key === "defaultLanguage") {
        const language = String(source[key] ?? "").trim().toLowerCase();
        normalized.defaultLanguage = language === "fil" || language === "tl" ? "fil" : "en";
        continue;
      }
      if (key === "sessionTimeoutMinutes") {
        const minutes = Number(source[key]);
        normalized.sessionTimeoutMinutes = Number.isFinite(minutes)
          ? Math.min(43200, Math.max(15, Math.trunc(minutes)))
          : platformSettingDefaults.sessionTimeoutMinutes;
        continue;
      }
      normalized[key] = Boolean(source[key]);
    }
    return normalized;
  }

  function getDangerousPlatformSettingPrompt(key, nextEnabled) {
    const entry = platformSettingDangerousPrompts[key];
    if (!entry) {
      return "";
    }
    return nextEnabled ? String(entry.enable || "") : String(entry.disable || "");
  }

