  //ito pwedi idelete
  // Reads or derives category trigger buttons for the current super admin flow.
  function getCategoryTriggerButtons() {
    return elements.categoryNavTriggers.filter((button) => button instanceof HTMLElement);
  }
  //hanggang dito

  // Reads or derives store type trigger buttons for the current super admin flow.
  function getStoreTypeTriggerButtons() {
    return elements.storeTypeNavTriggers.filter((button) => button instanceof HTMLElement);
  }

  // Checks whether event within element is true for the current record or UI state.
  function isEventWithinElement(event, element) {
    if (!(element instanceof HTMLElement) || !event) {
      return false;
    }

    if (typeof event.composedPath === "function") {
      const eventPath = event.composedPath();
      if (Array.isArray(eventPath) && eventPath.includes(element)) {
        return true;
      }
    }

    return event.target instanceof Node && element.contains(event.target);
  }

  // Normalizes category name before comparison or storage.
  function normalizeCategoryName(value, { preserveTrailingSpace = false } = {}) {
    const compactedValue = String(value ?? "")
      .replace(/\s+/g, " ")
      .replace(/^\s+/, "");

    if (!compactedValue) {
      return "";
    }

    const hasTrailingSpace = preserveTrailingSpace && /\s$/.test(compactedValue);
    const formattedCoreValue = hasTrailingSpace
      ? compactedValue.slice(0, -1)
      : compactedValue.trimEnd();

    return hasTrailingSpace ? `${formattedCoreValue} ` : formattedCoreValue;
  }

  // Normalizes category values before comparison or storage.
  function normalizeCategoryValues(values) {
    const rawValues = Array.isArray(values)
      ? values
      : values === null || values === undefined
        ? []
        : [values];
    const seen = new Set();
    const normalizedValues = [];

    for (const value of rawValues) {
      const normalizedCategory = normalizeCategoryName(value);
      const normalizedKey = normalizedCategory.toLowerCase();
      if (!normalizedCategory || seen.has(normalizedKey)) {
        continue;
      }

      seen.add(normalizedKey);
      normalizedValues.push(normalizedCategory);
    }

    return normalizedValues.sort((left, right) =>
      left.localeCompare(right, undefined, { sensitivity: "base" }),
    );
  }

  // Normalizes store type values before comparison or storage.
  function normalizeStoreTypeValues(values) {
    const rawValues = Array.isArray(values)
      ? values
      : values === null || values === undefined
        ? []
        : [values];
    const seen = new Set();
    const normalizedValues = [];

    for (const value of rawValues) {
      const normalizedStoreType = normalizeCategoryName(
        value && typeof value === "object"
          ? value.name ?? value.storeType ?? value.type ?? value.label ?? value.title
          : value,
      );
      const normalizedKey = normalizedStoreType.toLowerCase();
      if (!normalizedStoreType || seen.has(normalizedKey)) {
        continue;
      }

      seen.add(normalizedKey);
      normalizedValues.push(normalizedStoreType);
    }

    return normalizedValues.sort((left, right) =>
      left.localeCompare(right, undefined, { sensitivity: "base" }),
    );
  }

  // Normalizes store type status before comparison or storage.
  function normalizeStoreTypeStatus(value) {
    return String(value ?? "").trim().toLowerCase() === "inactive"
      ? "inactive"
      : "active";
  }

  function normalizeStoreTypeCategoryStatus(value) {
    const normalizedValue = String(value ?? "").trim().toLowerCase();
    return ["inactive", "deactivated", "disabled", "off"].includes(normalizedValue)
      ? "inactive"
      : "active";
  }

  // Normalizes store type number before comparison or storage.
  function normalizeStoreTypeNumber(value) {
    const numberValue = Number(value ?? 0);
    return Number.isFinite(numberValue) && numberValue >= 0 ? numberValue : 0;
  }

  // Keeps business type imagery limited to browser-safe image sources.
  function normalizeBusinessTypeImageUrl(value) {
    const imageUrl = String(value ?? "").trim();
    if (
      imageUrl.startsWith("/")
      || imageUrl.startsWith("data:image/")
      || /^https?:\/\//i.test(imageUrl)
    ) {
      return imageUrl;
    }
    return "";
  }

  // Normalizes optional per-category details returned with a business type.
  function normalizeStoreTypeCategoryStats(value) {
    const sourceValues = Array.isArray(value)
      ? value
      : value && typeof value === "object"
        ? Object.entries(value).map(([name, details]) => ({
            name,
            ...(details && typeof details === "object"
              ? details
              : { productCount: details }),
          }))
        : [];
    const seen = new Map();

    for (const source of sourceValues) {
      const categoryName = normalizeCategoryName(
        source?.name ?? source?.category ?? source?.label,
      );
      if (!categoryName) {
        continue;
      }

      const key = categoryName.toLowerCase();
      if (!seen.has(key)) {
        seen.set(key, {
          name: categoryName,
          productCount: Math.trunc(
            normalizeStoreTypeNumber(source?.productCount ?? source?.count ?? source?.items),
          ),
          imageUrl: normalizeBusinessTypeImageUrl(
            source?.imageUrl ?? source?.mainImageUrl ?? source?.thumbnailUrl,
          ),
          iconImageUrl: normalizeBusinessTypeImageUrl(
            source?.iconImageUrl ?? source?.iconUrl ?? source?.categoryIconUrl,
          ),
          iconName: normalizeLucideCategoryIconName(
            source?.iconName ?? source?.lucideIconName ?? source?.categoryIconName,
          ),
          status: normalizeStoreTypeCategoryStatus(
            source?.status ?? source?.categoryStatus ?? source?.state,
          ),
        });
      }
    }

    return [...seen.values()];
  }

  // Normalizes store type record before comparison or storage.
  function normalizePlatformIdValue(value) {
    return String(value ?? "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 64);
  }

  function slugifyPlatformIdValue(name) {
    const fromName = normalizePlatformIdValue(name);
    return fromName || `platform-${Date.now().toString(36)}`;
  }

  function inferPlatformIdFromName(name) {
    const key = String(name || "")
      .trim()
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
    if (!key) return "shop";
    if (
      key.includes("resort")
      || key.includes("villa")
      || key.includes("beach club")
    ) {
      return "resort";
    }
    if (
      key.includes("hotel")
      || key.includes("hote ")
      || key.includes("lodging")
      || (/\bhotes?\b/.test(key) && key.includes("restaurant"))
    ) {
      return "hotels";
    }
    if (
      key.includes("grocery")
      || key.includes("groceries")
      || key.includes("supermarket")
      || key.includes("convenience")
      || key.includes("minimart")
      || key.includes("sari sari")
    ) {
      return "groceries";
    }
    if (
      key === "food"
      || key === "foods"
      || key.includes("restaurant")
      || key.includes("dining")
      || key.includes("cafe")
    ) {
      return "food";
    }
    return "shop";
  }

  function resolvePlatformStorefrontMode(source = {}, platformId = "") {
    const raw = String(source.storefrontMode ?? source.mode ?? source.verticalMode ?? "")
      .trim()
      .toLowerCase();
    if (raw === "booking" || raw === "commerce") {
      return raw;
    }
    const id = normalizePlatformIdValue(platformId || source.id || source.platformId);
    if (id === "hotels" || id === "resort") {
      return "booking";
    }
    return "commerce";
  }

  function normalizePlatformRecord(value, options = {}) {
    const source = value && typeof value === "object" ? value : {};
    const name = String(source.name ?? source.label ?? source.title ?? value ?? "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 80);
    const explicitId = normalizePlatformIdValue(source.id ?? source.platformId ?? source.slug);
    const id = explicitId || (name ? slugifyPlatformIdValue(name) : "");
    if (!id || !name) {
      return null;
    }
    const statusValue = String(source.status ?? "active").trim().toLowerCase();
    const sortOrderRaw = Number(source.sortOrder ?? source.order ?? options.fallbackSortOrder ?? 0);
    const comingSoonRaw = source.comingSoon ?? source.isComingSoon ?? source.soon;
    const primaryColorRaw = String(
      source.primaryColor ?? source.color ?? source.accentColor ?? "",
    )
      .trim()
      .toLowerCase();
    const secondaryColorRaw = String(
      source.secondaryColor ?? source.secondaryAccent ?? "",
    )
      .trim()
      .toLowerCase();
    const defaultPrimaryById = {
      shop: "#2563eb",
      food: "#ea580c",
      hotels: "#7c3aed",
      resort: "#0891b2",
      groceries: "#16a34a",
    };
    const primaryColor = /^#[0-9a-f]{6}$/.test(primaryColorRaw)
      ? primaryColorRaw
      : (defaultPrimaryById[id] || "#2563eb");
    const secondaryColor = /^#[0-9a-f]{6}$/.test(secondaryColorRaw) ? secondaryColorRaw : "";
    return {
      id,
      name,
      status: statusValue === "inactive" ? "inactive" : "active",
      sortOrder: Number.isFinite(sortOrderRaw) ? Math.trunc(sortOrderRaw) : 0,
      iconName: normalizeLucideCategoryIconName(source.iconName ?? source.lucideIconName),
      comingSoon: comingSoonRaw === true || String(comingSoonRaw).trim().toLowerCase() === "true",
      heroImageUrl: normalizeBusinessTypeImageUrl(
        source.heroImageUrl ?? source.imageUrl ?? source.coverImageUrl,
      ),
      iconImageUrl: normalizeBusinessTypeImageUrl(source.iconImageUrl ?? source.iconUrl)
        || builtInPlatformArtUrls[id]
        || "",
      businessTypeCount: Math.trunc(normalizeStoreTypeNumber(source.businessTypeCount)),
      primaryColor,
      secondaryColor,
      storefrontMode: resolvePlatformStorefrontMode(source, id),
    };
  }

  function getPlatformRecordById(platformId) {
    const key = normalizePlatformIdValue(platformId);
    return state.platformDetails.find((platform) => platform.id === key) || null;
  }

  function getPlatformLabel(platformId) {
    const record = getPlatformRecordById(platformId);
    if (record?.name) {
      return record.name;
    }
    const normalized = normalizePlatformIdValue(platformId);
    if (!normalized) {
      return "Shop";
    }
    return normalized.charAt(0).toUpperCase() + normalized.slice(1);
  }

  function setStoreTypePlatformDropdownOpen(isOpen) {
    const shouldOpen = Boolean(isOpen);
    if (elements.storeTypePlatformMenu instanceof HTMLElement) {
      elements.storeTypePlatformMenu.hidden = !shouldOpen;
    }
    if (elements.storeTypePlatformTrigger instanceof HTMLButtonElement) {
      elements.storeTypePlatformTrigger.setAttribute("aria-expanded", String(shouldOpen));
    }
    if (elements.storeTypePlatformDropdown instanceof HTMLElement) {
      elements.storeTypePlatformDropdown.classList.toggle("is-open", shouldOpen);
    }
  }

  function syncStoreTypePlatformDropdownLabel() {
    const select = elements.storeTypePlatformSelect;
    const selectedOption = select instanceof HTMLSelectElement ? select.selectedOptions?.[0] : null;
    const label = String(selectedOption?.textContent || getPlatformLabel(select?.value) || "Shop").trim();
    if (elements.storeTypePlatformLabel instanceof HTMLElement) {
      elements.storeTypePlatformLabel.textContent = label || "Shop";
    }
    if (!(elements.storeTypePlatformMenu instanceof HTMLElement)) {
      return;
    }
    const selectedValue = normalizePlatformIdValue(select?.value) || "shop";
    for (const option of elements.storeTypePlatformMenu.querySelectorAll("[data-store-type-platform-option]")) {
      if (!(option instanceof HTMLElement)) {
        continue;
      }
      const isSelected = normalizePlatformIdValue(option.dataset.storeTypePlatformOption) === selectedValue;
      option.classList.toggle("is-selected", isSelected);
      option.setAttribute("aria-checked", String(isSelected));
    }
  }

  function syncStoreTypePlatformSelect(selectedPlatformId = "shop") {
    const select = elements.storeTypePlatformSelect;
    if (!(select instanceof HTMLSelectElement)) {
      return;
    }
    const platforms = state.platformDetails.length
      ? state.platformDetails
      : [
          { id: "shop", name: "Shop", status: "active" },
          { id: "food", name: "Food", status: "active" },
          { id: "hotels", name: "Hotels", status: "active" },
          { id: "groceries", name: "Groceries", status: "active" },
        ];
    const preferred = normalizePlatformIdValue(selectedPlatformId) || "shop";
    select.replaceChildren();
    if (elements.storeTypePlatformMenu instanceof HTMLElement) {
      elements.storeTypePlatformMenu.replaceChildren();
    }
    for (const platform of platforms) {
      const option = document.createElement("option");
      option.value = platform.id;
      option.textContent = platform.status === "inactive"
        ? `${platform.name} (Inactive)`
        : platform.name;
      select.append(option);

      if (elements.storeTypePlatformMenu instanceof HTMLElement) {
        const menuOption = document.createElement("button");
        menuOption.type = "button";
        menuOption.className = "super-admin-company-card__action-item super-admin-ban-modal__reason-option";
        menuOption.setAttribute("role", "menuitemradio");
        menuOption.dataset.storeTypePlatformOption = platform.id;
        menuOption.textContent = option.textContent;
        menuOption.addEventListener("click", () => {
          select.value = platform.id;
          select.dispatchEvent(new Event("change", { bubbles: true }));
          syncStoreTypePlatformDropdownLabel();
          setStoreTypePlatformDropdownOpen(false);
          elements.storeTypePlatformTrigger?.focus?.();
        });
        elements.storeTypePlatformMenu.append(menuOption);
      }
    }
    if (![...select.options].some((option) => option.value === preferred)) {
      const fallback = document.createElement("option");
      fallback.value = preferred;
      fallback.textContent = getPlatformLabel(preferred);
      select.append(fallback);
      if (elements.storeTypePlatformMenu instanceof HTMLElement) {
        const menuOption = document.createElement("button");
        menuOption.type = "button";
        menuOption.className = "super-admin-company-card__action-item super-admin-ban-modal__reason-option";
        menuOption.setAttribute("role", "menuitemradio");
        menuOption.dataset.storeTypePlatformOption = preferred;
        menuOption.textContent = fallback.textContent;
        menuOption.addEventListener("click", () => {
          select.value = preferred;
          select.dispatchEvent(new Event("change", { bubbles: true }));
          syncStoreTypePlatformDropdownLabel();
          setStoreTypePlatformDropdownOpen(false);
          elements.storeTypePlatformTrigger?.focus?.();
        });
        elements.storeTypePlatformMenu.append(menuOption);
      }
    }
    select.value = preferred;
    syncStoreTypePlatformDropdownLabel();
    setStoreTypePlatformDropdownOpen(false);
  }

  function setPlatformData(platformDetails) {
    state.platformDetails = (Array.isArray(platformDetails) ? platformDetails : [])
      .map((item, index) => normalizePlatformRecord(item, { fallbackSortOrder: index + 1 }))
      .filter(Boolean)
      .sort((left, right) => {
        if (left.sortOrder !== right.sortOrder) {
          return left.sortOrder - right.sortOrder;
        }
        return left.name.localeCompare(right.name, undefined, { sensitivity: "base" });
      });
    state.platforms = state.platformDetails.map((platform) => platform.id);
    if (elements.platformTotal) {
      elements.platformTotal.textContent = `(${numberText(state.platformDetails.length)})`;
    }
    syncStoreTypePlatformSelect(elements.storeTypePlatformSelect?.value || "shop");
    renderPlatforms();
    renderPlatformSubNav(state.platformDetails);
    try {
      window.dispatchEvent(new CustomEvent("gms:platforms-updated", {
        detail: { platforms: state.platformDetails.slice() },
      }));
    } catch (_) {
      // Ignore environments without CustomEvent support.
    }
  }

  function getPlatformPresentation(platform) {
    const key = `${platform?.id || ""} ${platform?.name || ""}`.trim().toLowerCase();
    if (/(grocery|groceries|supermarket|minimart)/.test(key)) {
      return {
        iconClass: "fa-basket-shopping",
        tagline: "Everyday essentials and local markets",
        description: "Manage the Groceries entry point, its connected business types, and availability in the buyer app.",
        imageUrl: "/assets/root-login/root-login-hero-wide.png",
      };
    }
    if (/(food|restaurant|dining|cafe)/.test(key)) {
      return {
        iconClass: "fa-utensils",
        tagline: "Restaurants, meals, and local dining",
        description: "Manage the Food entry point, its connected business types, and availability in the buyer app.",
        imageUrl: "/assets/business-types/restaurant-hero.webp",
      };
    }
    if (/(hotel|stay|lodging|resort)/.test(key)) {
      return {
        iconClass: "fa-hotel",
        tagline: "Stays, rooms, and guest experiences",
        description: "Manage the Hotels entry point, its connected business types, and availability in the buyer app.",
        imageUrl: "/assets/admin-signup/signup-hero-background.png",
      };
    }
    return {
      iconClass: "fa-bag-shopping",
      tagline: "Stores, products, and everyday shopping",
      description: "Manage this buyer entry platform, its connected business types, and visibility across the app.",
      imageUrl: "/assets/root-login/root-login-hero-wide.png",
    };
  }

  function getPlatformBusinessTypes(platformId) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    return state.storeTypeDetails.filter(
      (record) => normalizePlatformIdValue(record.platformId) === normalizedPlatformId,
    );
  }

  // Counts business-type toggles for the platform Business Types hero stat (green = on, red = off).
  function getPlatformBusinessTypeToggleCounts(platformId) {
    const records = getPlatformBusinessTypes(platformId);
    let active = 0;
    let inactive = 0;
    for (const record of records) {
      if (normalizeStoreTypeStatus(record?.status) === "inactive") {
        inactive += 1;
      } else {
        active += 1;
      }
    }
    return { active, inactive, total: records.length };
  }

  function createPlatformBusinessTypeCard(record, index, platformId = "") {
    const presentation = getBusinessTypePresentation(record.name);
    const colors = getBusinessTypeCategoryIconColors(record.name, index);
    const card = document.createElement("article");
    card.className = "business-type-showcase__category-card platform-showcase__business-type-card";
    card.classList.toggle("is-category-inactive", record.status === "inactive");
    card.dataset.platformBusinessTypeName = record.name.toLowerCase();
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `Open ${record.name} business type`);

    const openBusinessType = () => {
      const sourcePlatformId = normalizePlatformIdValue(platformId || record.platformId);
      // Remember exact Platforms visual so return does not land at page end.
      sectionWindowScrollY.platforms = getWindowScrollY();
      platformsReturnPlatformId = sourcePlatformId;
      if (sourcePlatformId) {
        state.selectedPlatformNavId = sourcePlatformId;
        savePlatformSubNav(sourcePlatformId);
      }
      handleStoreTypeSubNavClick(record.name, { fromSection: "platforms" });
    };
    card.addEventListener("click", openBusinessType);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openBusinessType();
      }
    });

    const media = document.createElement("span");
    media.className = "business-type-showcase__category-media";
    const mediaFrame = document.createElement("span");
    mediaFrame.className = "business-type-showcase__category-media-frame";
    const image = document.createElement("img");
    image.className = "business-type-showcase__category-image";
    image.src = record.heroImageUrl || presentation.imageUrl;
    image.alt = record.name;
    image.loading = "lazy";
    image.decoding = "async";
    setBusinessTypeImageFallback(image, presentation.imageUrl, media);
    mediaFrame.append(image);

    const businessTypeIcon = document.createElement("span");
    businessTypeIcon.className = "business-type-showcase__category-icon";
    businessTypeIcon.style.setProperty("--business-type-category-icon-bg", colors.background);
    businessTypeIcon.style.setProperty("--business-type-category-icon-color", colors.color);
    const iconSurface = document.createElement("span");
    iconSurface.className = "business-type-showcase__category-icon-surface";
    const iconImageUrl = normalizeBusinessTypeImageUrl(record.iconImageUrl);
    const lucideIconName = normalizeLucideCategoryIconName(record.iconName);
    if (iconImageUrl) {
      const iconImage = document.createElement("img");
      iconImage.src = iconImageUrl;
      iconImage.alt = "";
      iconSurface.append(iconImage);
    } else if (lucideIconName) {
      businessTypeIcon.classList.add("has-lucide-icon");
      iconSurface.innerHTML = createLucideCategoryIconSvg(lucideIconName);
    } else {
      const fallbackIcon = document.createElement("i");
      fallbackIcon.className = `fa-solid ${presentation.iconClass}`;
      fallbackIcon.setAttribute("aria-hidden", "true");
      iconSurface.append(fallbackIcon);
    }
    businessTypeIcon.append(iconSurface);
    media.append(mediaFrame, businessTypeIcon);

    const copy = document.createElement("span");
    copy.className = "business-type-showcase__category-copy";
    const name = document.createElement("strong");
    name.textContent = record.name;
    const meta = document.createElement("span");
    meta.textContent = `${numberText(record.categories.length)} ${record.categories.length === 1 ? "category" : "categories"}`;
    copy.append(name, meta);
    card.append(media, copy);
    return card;
  }

  function createShowcaseCategoryHeadingTitle(label, countValue) {
    const titleRow = document.createElement("div");
    titleRow.className = "business-type-showcase__categories-title";
    const title = document.createElement("h4");
    title.textContent = label;
    const count = document.createElement("span");
    count.className = "super-admin-company-status-nav__count";
    count.textContent = numberText(countValue);
    titleRow.append(title, count);
    return titleRow;
  }

  function createPlatformShowcase(platform) {
    const presentation = getPlatformPresentation(platform);
    const showcase = document.createElement("article");
    showcase.className = "category-chip business-type-showcase platform-showcase";
    showcase.dataset.platformId = platform.id;

    const hero = document.createElement("div");
    hero.className = "business-type-showcase__hero";

    const content = document.createElement("div");
    content.className = "business-type-showcase__content";

    const identity = document.createElement("div");
    identity.className = "business-type-showcase__identity";

    const iconWrap = document.createElement("span");
    iconWrap.className = "business-type-showcase__icon-wrap";
    const icon = document.createElement("span");
    icon.className = "business-type-showcase__icon";
    const iconSurface = document.createElement("span");
    iconSurface.className = "business-type-showcase__icon-surface";
    const iconImageUrl = normalizeBusinessTypeImageUrl(platform.iconImageUrl)
      || builtInPlatformArtUrls[platform.id]
      || "";
    const lucideIconName = normalizeLucideCategoryIconName(platform.iconName);
    if (iconImageUrl) {
      iconWrap.classList.add("has-platform-art");
      icon.classList.add("has-platform-art");
      const iconImage = document.createElement("img");
      iconImage.src = iconImageUrl;
      iconImage.alt = `${platform.name} 3D art`;
      iconImage.loading = "lazy";
      iconImage.decoding = "async";
      iconSurface.append(iconImage);
    } else if (lucideIconName) {
      icon.classList.add("has-lucide-icon");
      iconSurface.innerHTML = createLucideCategoryIconSvg(lucideIconName);
    } else {
      const fallbackIcon = document.createElement("i");
      fallbackIcon.className = `fa-solid ${presentation.iconClass}`;
      fallbackIcon.setAttribute("aria-hidden", "true");
      iconSurface.append(fallbackIcon);
    }
    icon.append(iconSurface);
    iconWrap.append(icon);

    const heading = document.createElement("div");
    heading.className = "business-type-showcase__heading";
    const titleRow = document.createElement("div");
    titleRow.className = "business-type-showcase__title-row";
    const title = document.createElement("h3");
    title.className = "business-type-showcase__title";
    title.textContent = platform.name;
    const isInactive = platform.status === "inactive";
    const platformIndex = state.platformDetails.findIndex((entry) => entry.id === platform.id);
    const canMoveUp = platformIndex > 0;
    const canMoveDown = platformIndex >= 0 && platformIndex < state.platformDetails.length - 1;
    const platformQuickActions = [];
    platformQuickActions.push({
      label: "Edit",
      icon: '<path d="M13 21h8"></path><path d="M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z"></path>',
      onSelect: () => openPlatformModal(platform),
    });
    if (canMoveUp) {
      platformQuickActions.push({
        label: "Move up",
        icon: '<path d="m18 15-6-6-6 6"></path>',
        onSelect: () => void handleReorderPlatform(platform.id, "up"),
      });
    }
    if (canMoveDown) {
      platformQuickActions.push({
        label: "Move down",
        icon: '<path d="m6 9 6 6 6-6"></path>',
        onSelect: () => void handleReorderPlatform(platform.id, "down"),
      });
    }
    platformQuickActions.push(
      {
        label: isInactive ? "Activate" : "Deactivate",
        tone: isInactive ? "positive" : "danger",
        icon: '<path d="M12 2v10"></path><path d="M18.4 6.6a9 9 0 1 1-12.8 0"></path>',
        onSelect: () => void handleSetPlatformStatus(platform, isInactive ? "active" : "inactive"),
      },
      {
        label: "Delete",
        tone: "danger",
        icon: defaultTrashIconPaths,
        onSelect: () => void handleDeletePlatform(platform.id, platform.name),
      },
    );
    const titleActions = document.createElement("div");
    titleActions.className = "business-type-showcase__title-actions";
    titleActions.append(
      createBusinessTypeQuickActions(`Platform actions for ${platform.name}`, platformQuickActions),
    );
    const tagline = document.createElement("p");
    tagline.className = "business-type-showcase__tagline";
    tagline.textContent = presentation.tagline;
    const statusPill = document.createElement("span");
    statusPill.className = "business-type-card__status";
    statusPill.textContent = isInactive
      ? "Inactive"
      : (platform.comingSoon ? "Coming Soon" : "Active");
    statusPill.classList.toggle("is-inactive", isInactive || platform.comingSoon);
    titleRow.append(title, statusPill, titleActions);
    heading.append(titleRow, tagline);
    identity.append(iconWrap, heading);

    const description = document.createElement("p");
    description.className = "business-type-showcase__description";
    description.textContent = presentation.description;

    const stats = document.createElement("div");
    stats.className = "business-type-showcase__stats";
    const createPlatformStat = (iconPaths, label, value, options = {}) => {
      const stat = document.createElement("div");
      stat.className = "business-type-showcase__stat";
      if (options.className) {
        stat.classList.add(options.className);
      }
      if (options.iconColor) {
        stat.style.setProperty("--platform-color", options.iconColor);
      }
      const statIcon = document.createElement("span");
      statIcon.className = "business-type-showcase__stat-icon";
      statIcon.innerHTML = createIconSvg(iconPaths);
      if (options.iconColor) {
        statIcon.style.color = options.iconColor;
      }
      const statCopy = document.createElement("span");
      statCopy.className = "business-type-showcase__stat-copy";
      const hasLeading = options.leading instanceof Node;
      const valueText = String(value ?? "").trim();
      if (hasLeading) {
        const valueRow = document.createElement("span");
        valueRow.className = "business-type-showcase__stat-value-row";
        if (valueText) {
          const statValue = document.createElement("strong");
          statValue.textContent = valueText;
          valueRow.append(statValue);
        }
        valueRow.append(options.leading);
        statCopy.append(valueRow);
      } else {
        const statValue = document.createElement("strong");
        statValue.textContent = valueText;
        statCopy.append(statValue);
      }
      const statLabel = document.createElement("span");
      statLabel.textContent = label;
      statCopy.append(statLabel);
      stat.append(statIcon, statCopy);
      return stat;
    };
    const platformColor = normalizeHexColorValue(platform.primaryColor, platform.primaryColor || "#2563eb");
    const businessTypeToggleCounts = getPlatformBusinessTypeToggleCounts(platform.id);
    stats.append(
      createPlatformStat(
        '<rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect>',
        "Business Types",
        "",
        {
          className: "business-type-showcase__stat--business-types",
          leading: createBusinessTypeCategoryStatusDots(
            businessTypeToggleCounts.active,
            businessTypeToggleCounts.inactive,
          ),
        },
      ),
      createPlatformStat(
        '<path d="M12 22a1 1 0 0 1 0-20 10 9 0 0 1 10 9 5 5 0 0 1-5 5h-2.25a1.75 1.75 0 0 0-1.4 2.8l.3.4a1.75 1.75 0 0 1-1.4 2.8z"></path><circle cx="13.5" cy="6.5" r=".5" fill="currentColor"></circle><circle cx="17.5" cy="10.5" r=".5" fill="currentColor"></circle><circle cx="6.5" cy="12.5" r=".5" fill="currentColor"></circle><circle cx="8.5" cy="7.5" r=".5" fill="currentColor"></circle>',
        "Color",
        platformColor.toUpperCase(),
        {
          className: "business-type-showcase__stat--color",
          iconColor: platformColor,
        },
      ),
    );

    const settings = document.createElement("div");
    settings.className = "business-type-showcase__settings";
    settings.append(createShowcaseIdSetting("Platform ID", platform.id));

    content.append(identity, description, stats, settings);

    const media = document.createElement("div");
    media.className = "business-type-showcase__media platform-showcase__media";
    const heroImage = document.createElement("img");
    heroImage.className = "business-type-showcase__hero-image";
    heroImage.alt = `${platform.name} platform`;
    heroImage.loading = "lazy";
    heroImage.decoding = "async";
    const heroImageUrl = normalizeBusinessTypeImageUrl(platform.heroImageUrl);
    if (heroImageUrl) {
      heroImage.src = heroImageUrl;
      setBusinessTypeImageFallback(heroImage, "", media);
    } else {
      heroImage.hidden = true;
      media.classList.add("is-image-missing");
    }

    const mediaSurface = document.createElement("span");
    mediaSurface.className = "business-type-showcase__media-edit-surface";
    mediaSurface.append(heroImage);
    media.append(mediaSurface);
    hero.append(content, media);

    const connectedBusinessTypes = getPlatformBusinessTypes(platform.id);
    const businessTypeSection = document.createElement("section");
    businessTypeSection.className = "business-type-showcase__categories platform-showcase__business-types";
    const businessTypeCarouselLimit = 8;
    const hasBusinessTypeCarousel = connectedBusinessTypes.length > businessTypeCarouselLimit;
    businessTypeSection.classList.toggle("has-carousel", hasBusinessTypeCarousel);
    businessTypeSection.setAttribute("aria-label", `${platform.name} business types`);
    const businessTypeHeader = document.createElement("div");
    businessTypeHeader.className = "business-type-showcase__categories-header";
    const businessTypeHeading = document.createElement("div");
    businessTypeHeading.className = "business-type-showcase__categories-copy";
    const businessTypeTitle = createShowcaseCategoryHeadingTitle(
      "Business Types",
      connectedBusinessTypes.length,
    );
    const businessTypeDescription = document.createElement("p");
    businessTypeDescription.textContent = `Business types assigned to ${platform.name}.`;
    businessTypeHeading.append(businessTypeTitle, businessTypeDescription);

    const businessTypeActions = document.createElement("div");
    businessTypeActions.className = "business-type-showcase__categories-actions";

    const businessTypeCarousel = document.createElement("div");
    businessTypeCarousel.className = "business-type-showcase__category-carousel";
    businessTypeCarousel.classList.toggle("is-carousel", hasBusinessTypeCarousel);

    const businessTypeGrid = document.createElement("div");
    businessTypeGrid.className = "business-type-showcase__category-grid platform-showcase__business-type-grid";
    businessTypeGrid.classList.toggle("is-carousel", hasBusinessTypeCarousel);
    businessTypeGrid.style.setProperty(
      "--business-type-category-count",
      String(businessTypeCarouselLimit),
    );
    businessTypeGrid.style.setProperty(
      "--business-type-category-column-width",
      `calc((100% - (var(--business-type-category-gap) * ${businessTypeCarouselLimit - 1})) / ${businessTypeCarouselLimit})`,
    );
    businessTypeGrid.setAttribute(
      "aria-label",
      hasBusinessTypeCarousel ? `Scrollable ${platform.name} business types` : `${platform.name} business types`,
    );

    if (hasBusinessTypeCarousel) {
      const carouselControls = document.createElement("span");
      carouselControls.className = "business-type-showcase__carousel-controls";

      const previousBusinessTypeButton = document.createElement("button");
      previousBusinessTypeButton.type = "button";
      previousBusinessTypeButton.className = "business-type-showcase__carousel-button";
      previousBusinessTypeButton.setAttribute("aria-label", `Previous ${platform.name} business types`);
      previousBusinessTypeButton.title = "Previous business types";
      previousBusinessTypeButton.innerHTML = createIconSvg('<path d="m15 18-6-6 6-6"></path>');
      previousBusinessTypeButton.addEventListener("click", (event) => {
        event.stopPropagation();
        scrollBusinessTypeCategoryCarousel(businessTypeGrid, -1);
      });

      const nextBusinessTypeButton = document.createElement("button");
      nextBusinessTypeButton.type = "button";
      nextBusinessTypeButton.className = "business-type-showcase__carousel-button";
      nextBusinessTypeButton.setAttribute("aria-label", `Next ${platform.name} business types`);
      nextBusinessTypeButton.title = "Next business types";
      nextBusinessTypeButton.innerHTML = createIconSvg('<path d="m9 18 6-6-6-6"></path>');
      nextBusinessTypeButton.addEventListener("click", (event) => {
        event.stopPropagation();
        scrollBusinessTypeCategoryCarousel(businessTypeGrid, 1);
      });

      carouselControls.append(previousBusinessTypeButton, nextBusinessTypeButton);
      businessTypeActions.append(carouselControls);
    }
    businessTypeHeader.append(businessTypeHeading);
    if (businessTypeActions.childElementCount) {
      businessTypeHeader.append(businessTypeActions);
    }

    if (connectedBusinessTypes.length) {
      connectedBusinessTypes.forEach((record, index) => {
        businessTypeGrid.append(createPlatformBusinessTypeCard(record, index, platform.id));
      });
    } else {
      const empty = document.createElement("div");
      empty.className = "business-type-showcase__empty platform-showcase__business-type-empty";
      empty.innerHTML = `${createIconSvg('<rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect>')}<span>No business types assigned yet.</span>`;
      businessTypeGrid.append(empty);
    }
    businessTypeCarousel.append(businessTypeGrid);
    businessTypeSection.append(businessTypeHeader, businessTypeCarousel);
    showcase.append(hero, businessTypeSection);
    return showcase;
  }

  function getFilteredPlatforms() {
    const searchTerm = String(state.platformSearch || "")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
    if (!searchTerm) {
      return state.platformDetails.slice();
    }

    return state.platformDetails.filter((platform) => {
      const presentation = getPlatformPresentation(platform);
      const businessTypes = getPlatformBusinessTypes(platform.id);
      const haystack = [
        platform.id,
        platform.name,
        platform.status,
        platform.comingSoon ? "coming soon" : "available",
        platform.storefrontMode,
        presentation.tagline,
        presentation.description,
        ...businessTypes.flatMap((record) => [record?.name, record?.status]),
      ]
        .map((value) => String(value || "").toLowerCase())
        .join(" ");
      return haystack.includes(searchTerm);
    });
  }

  function setPlatformSearch(value) {
    state.platformSearch = String(value || "");
    if (
      elements.platformSearch instanceof HTMLInputElement
      && elements.platformSearch.value !== state.platformSearch
    ) {
      elements.platformSearch.value = state.platformSearch;
    }
    renderPlatforms();
  }

  function renderPlatforms() {
    if (!(elements.platformList instanceof HTMLElement)) {
      return;
    }
    const searchTerm = String(state.platformSearch || "").trim();
    const platforms = getFilteredPlatforms();
    const total = state.platformDetails.length;
    if (elements.platformTotal) {
      elements.platformTotal.textContent = searchTerm
        ? `(${numberText(platforms.length)} / ${numberText(total)})`
        : `(${numberText(total)})`;
    }

    if (state.platformsLoading) {
      if (!total) {
        paintSubNavSkeleton(elements.platformSubNav, readSubNavSkeletonCount("platforms"));
      }
      paintShowcaseSkeletonList(elements.platformList, total || 3);
      refreshPlatformSubNavScrollSpy();
      return;
    }

    elements.platformList.classList.remove("is-skeleton-loading");
    elements.platformList.replaceChildren();
    if (!total) {
      const empty = document.createElement("div");
      empty.className = "empty-state";
      empty.textContent = "No buyer platforms yet.";
      elements.platformList.append(empty);
      refreshPlatformSubNavScrollSpy();
      return;
    }

    if (!platforms.length) {
      if (window.SuperAdminSearchState?.render) {
        window.SuperAdminSearchState.render(elements.platformList, {
          variant: "empty",
          message: `No platforms found for “${searchTerm}”.`,
          className: "super-admin-platform-search-state",
        });
      } else {
        const empty = document.createElement("div");
        empty.className = "empty-state";
        empty.textContent = `No platforms found for “${searchTerm}”.`;
        elements.platformList.append(empty);
      }
      refreshPlatformSubNavScrollSpy();
      return;
    }

    for (const platform of platforms) {
      elements.platformList.append(createPlatformShowcase(platform));
    }
    refreshPlatformSubNavScrollSpy();
    const pendingId = normalizePlatformIdValue(pendingPlatformFocusId);
    if (pendingId && state.activeSection === "platforms") {
      window.requestAnimationFrame(() => {
        focusPlatformShowcase(pendingId);
      });
    }
  }

  function getPlatformShowcaseById(platformId) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    if (!normalizedPlatformId || !(elements.platformList instanceof HTMLElement)) {
      return null;
    }
    // Direct platform cards only (avoid nested [data-platform-id] if any appear later).
    return Array.from(
      elements.platformList.querySelectorAll(":scope > .platform-showcase[data-platform-id], :scope > [data-platform-id].platform-showcase"),
    ).find(
      (item) => item instanceof HTMLElement
        && normalizePlatformIdValue(item.dataset.platformId) === normalizedPlatformId,
    ) || Array.from(elements.platformList.querySelectorAll(".platform-showcase[data-platform-id]")).find(
      (item) => item instanceof HTMLElement
        && normalizePlatformIdValue(item.dataset.platformId) === normalizedPlatformId,
    ) || null;
  }

  function lockPlatformSubNavScrollSpy(durationMs = 1800) {
    platformSubNavSpyLockUntil = Date.now() + Math.max(0, Number(durationMs) || 0);
  }

  function scrollSubNavButtonIntoLocalView(button) {
    if (!(button instanceof HTMLElement)) {
      return;
    }
    const scroller = button.closest(
      ".super-admin-company-status-nav, .super-admin-subnav-host, [data-super-admin-subnav]",
    );
    if (!(scroller instanceof HTMLElement)) {
      return;
    }
    const scrollerRect = scroller.getBoundingClientRect();
    const buttonRect = button.getBoundingClientRect();
    if (buttonRect.top < scrollerRect.top) {
      scroller.scrollTop -= scrollerRect.top - buttonRect.top;
      return;
    }
    if (buttonRect.bottom > scrollerRect.bottom) {
      scroller.scrollTop += buttonRect.bottom - scrollerRect.bottom;
    }
  }

  function syncPlatformSubNavSelection(platformId, { persist = true, scrollSubButton = true } = {}) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    if (!normalizedPlatformId) {
      return;
    }
    const changed = state.selectedPlatformNavId !== normalizedPlatformId;
    if (changed) {
      state.selectedPlatformNavId = normalizedPlatformId;
      if (persist) {
        savePlatformSubNav(normalizedPlatformId);
      }
    }
    if (!(elements.platformSubNav instanceof HTMLElement)) {
      return;
    }
    let activeButton = null;
    for (const button of elements.platformSubNav.querySelectorAll("[data-super-admin-platform-shortcut]")) {
      if (!(button instanceof HTMLElement)) {
        continue;
      }
      const isActive = normalizePlatformIdValue(button.dataset.superAdminPlatformShortcut) === normalizedPlatformId;
      button.classList.toggle("is-active", isActive);
      button.setAttribute("aria-pressed", isActive ? "true" : "false");
      if (isActive) {
        activeButton = button;
      }
    }
    if (scrollSubButton && activeButton instanceof HTMLElement) {
      // Local subnav only — never scrollIntoView (that jumps the whole page to the end).
      scrollSubNavButtonIntoLocalView(activeButton);
    }
  }

  function getScrollSpyFocusLine() {
    // Same line as teleport landing: sticky header bottom + breathing gap.
    if (typeof getShowcaseScrollMargin === "function") {
      const margin = getShowcaseScrollMargin();
      if (Number.isFinite(margin) && margin > 40) {
        return margin;
      }
    }
    return Math.min(168, Math.max(96, Math.round((window.innerHeight || 0) * 0.16)));
  }

  function updateScrollSpyDirection() {
    const y = window.scrollY || window.pageYOffset || 0;
    const delta = y - scrollSpyLastWindowY;
    if (delta > 1) {
      scrollSpyDirection = "down";
      scrollSpyLastWindowY = y;
    } else if (delta < -1) {
      scrollSpyDirection = "up";
      scrollSpyLastWindowY = y;
    }
    return scrollSpyDirection;
  }

  function isDocumentNearBottom(thresholdPx) {
    const viewportHeight = window.innerHeight || 0;
    const resolvedThreshold = Number.isFinite(thresholdPx)
      ? thresholdPx
      : Math.max(180, Math.round(viewportHeight * 0.28));
    const viewportBottom = window.scrollY + viewportHeight;
    const documentHeight = Math.max(
      document.documentElement?.scrollHeight || 0,
      document.body?.scrollHeight || 0,
    );
    return documentHeight > 0 && viewportBottom >= documentHeight - Math.max(24, resolvedThreshold);
  }

  // Active = card whose top meets the sticky header line.
  // Scroll down: switch when the next card top reaches the header.
  // Scroll up: keep the current card until the previous card top reaches the header
  // (do not flip early while the previous card is still far above the header).
  function pickActiveScrollSpyTarget(targets) {
    const connectedTargets = (Array.isArray(targets) ? targets : [])
      .filter((target) => target instanceof HTMLElement && target.isConnected);
    if (!connectedTargets.length) {
      return null;
    }

    const lastTarget = connectedTargets[connectedTargets.length - 1];
    if (isDocumentNearBottom()) {
      return lastTarget;
    }

    const direction = updateScrollSpyDirection();
    const focusLine = getScrollSpyFocusLine();
    // How far above the header a candidate may sit before we accept it on scroll-up.
    const upMeetBand = Math.max(28, Math.round(focusLine * 0.2));

    let crossedIndex = 0;
    for (let index = 0; index < connectedTargets.length; index += 1) {
      if (connectedTargets[index].getBoundingClientRect().top <= focusLine) {
        crossedIndex = index;
      } else {
        break;
      }
    }

    let activeIndex = crossedIndex;
    if (direction === "up") {
      // While the crossed card is still far above the header, keep the next card
      // (the one whose top just left the line) until the upper card actually meets it.
      while (
        activeIndex < connectedTargets.length - 1
        && connectedTargets[activeIndex].getBoundingClientRect().top < focusLine - upMeetBand
      ) {
        activeIndex += 1;
      }
    }

    // Last card can sit mid-viewport when there isn't enough scroll room left to
    // bring its top up to the focus line — promote it once it enters the upper half.
    if (activeIndex !== connectedTargets.length - 1) {
      const lastRect = lastTarget.getBoundingClientRect();
      const viewportHeight = window.innerHeight || 0;
      if (
        lastRect.top < viewportHeight * 0.55
        && lastRect.bottom > focusLine
        && isDocumentNearBottom(Math.max(240, Math.round(viewportHeight * 0.4)))
      ) {
        return lastTarget;
      }
    }

    return connectedTargets[activeIndex];
  }

  function scheduleScrollSpySync(kind) {
    if (kind === "platform") {
      if (platformSubNavSpyFrame) {
        return;
      }
      platformSubNavSpyFrame = window.requestAnimationFrame(() => {
        platformSubNavSpyFrame = 0;
        syncPlatformSubNavFromScroll();
      });
      return;
    }
    if (storeTypeSubNavSpyFrame) {
      return;
    }
    storeTypeSubNavSpyFrame = window.requestAnimationFrame(() => {
      storeTypeSubNavSpyFrame = 0;
      syncStoreTypeSubNavFromScroll();
    });
  }

  function syncPlatformSubNavFromScroll() {
    if (Date.now() < platformSubNavSpyLockUntil || state.activeSection !== "platforms") {
      return;
    }
    const activeTarget = pickActiveScrollSpyTarget(platformSubNavSpyTargets);
    const platformId = normalizePlatformIdValue(activeTarget?.dataset?.platformId);
    if (platformId) {
      syncPlatformSubNavSelection(platformId);
    }
  }

  function detachPlatformSubNavScrollSpy() {
    if (platformSubNavSpyObserver) {
      platformSubNavSpyObserver.disconnect();
      platformSubNavSpyObserver = null;
    }
    if (platformSubNavSpyFrame) {
      window.cancelAnimationFrame(platformSubNavSpyFrame);
      platformSubNavSpyFrame = 0;
    }
    if (platformSubNavSpyScrollBound) {
      window.removeEventListener("scroll", platformSubNavSpyScrollBound);
      window.removeEventListener("resize", platformSubNavSpyScrollBound);
      platformSubNavSpyScrollBound = null;
    }
    if (platformListEndPadResizeBound) {
      window.removeEventListener("resize", platformListEndPadResizeBound);
      platformListEndPadResizeBound = null;
    }
    platformSubNavSpyTargets = [];
    platformSubNavSpyRatios.clear();
  }

  function refreshPlatformSubNavScrollSpy() {
    detachPlatformSubNavScrollSpy();
    if (!(elements.platformList instanceof HTMLElement)) {
      return;
    }
    syncPlatformListEndPadding();
    platformSubNavSpyTargets = Array.from(
      elements.platformList.querySelectorAll(".platform-showcase[data-platform-id], .business-type-showcase[data-platform-id]"),
    ).filter((item) => item instanceof HTMLElement);
    if (!platformSubNavSpyTargets.length) {
      return;
    }

    platformSubNavSpyScrollBound = () => scheduleScrollSpySync("platform");
    platformListEndPadResizeBound = () => syncPlatformListEndPadding();
    window.addEventListener("scroll", platformSubNavSpyScrollBound, { passive: true });
    window.addEventListener("resize", platformSubNavSpyScrollBound, { passive: true });
    window.addEventListener("resize", platformListEndPadResizeBound, { passive: true });

    // IO nudges updates when cards enter/leave; scroll handler covers end-of-page pinning.
    platformSubNavSpyObserver = new IntersectionObserver(() => {
      scheduleScrollSpySync("platform");
    }, {
      root: null,
      rootMargin: "-8% 0px -35% 0px",
      threshold: [0, 0.1, 0.25, 0.5, 0.75, 1],
    });
    for (const target of platformSubNavSpyTargets) {
      platformSubNavSpyObserver.observe(target);
    }
    scheduleScrollSpySync("platform");
  }

  function focusPlatformShowcase(platformId) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    if (!normalizedPlatformId) {
      return false;
    }
    pendingPlatformFocusId = normalizedPlatformId;
    if (state.activeSection !== "platforms") {
      return false;
    }
    // loadPlatforms rebuilds the list — pop only the live post-render card.
    if (state.platformsLoading) {
      return false;
    }
    const targetElement = getPlatformShowcaseById(normalizedPlatformId);
    if (!(targetElement instanceof HTMLElement)) {
      return false;
    }
    lockPlatformSubNavScrollSpy(3200);
    syncPlatformSubNavSelection(normalizedPlatformId, { scrollSubButton: true });
    targetElement.setAttribute("tabindex", "-1");
    pendingPlatformFocusId = "";
    teleportShowcaseToHeader(targetElement, () => {
      lockPlatformSubNavScrollSpy(1200);
      const liveTarget = getPlatformShowcaseById(normalizedPlatformId);
      if (liveTarget instanceof HTMLElement) {
        liveTarget.focus({ preventScroll: true });
        playStoreTypeShowcasePop(liveTarget);
      }
    });
    return true;
  }

  function handlePlatformSubNavClick(platformId) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    if (!normalizedPlatformId) {
      return;
    }
    lockPlatformSubNavScrollSpy(3200);
    pendingPlatformFocusId = normalizedPlatformId;
    platformsReturnPlatformId = normalizedPlatformId;
    if (String(state.platformSearch || "").trim()) {
      setPlatformSearch("");
    }
    syncPlatformSubNavSelection(normalizedPlatformId, { scrollSubButton: true });
    const switchingSection = state.activeSection !== "platforms";
    if (switchingSection) {
      setActiveSection("platforms", {
        skipScrollMemory: true,
        forceScrollTop: 0,
        focusPlatformId: "",
        refocusPlatform: false,
      });
      return;
    }
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        focusPlatformShowcase(normalizedPlatformId);
      });
    });
  }

  function renderPlatformSubNav(platforms = state.platformDetails) {
    if (!(elements.platformSubNav instanceof HTMLElement)) {
      return;
    }
    const nextPlatforms = (Array.isArray(platforms) ? platforms : [])
      .filter((platform) => platform && normalizePlatformIdValue(platform.id));
    if (state.platformsLoading && !nextPlatforms.length) {
      paintSubNavSkeleton(elements.platformSubNav, readSubNavSkeletonCount("platforms"));
      return;
    }
    elements.platformSubNav.classList.remove("is-skeleton-loading");
    elements.platformSubNav.replaceChildren();

    if (
      state.selectedPlatformNavId
      && !nextPlatforms.some(
        (platform) => normalizePlatformIdValue(platform.id) === state.selectedPlatformNavId,
      )
    ) {
      state.selectedPlatformNavId = "";
    }
    savePlatformSubNav(state.selectedPlatformNavId);

    if (!nextPlatforms.length) {
      const emptyItem = document.createElement("span");
      emptyItem.className = "super-admin-company-status-nav__item super-admin-platform-subnav__empty";
      emptyItem.innerHTML = '<span class="super-admin-company-status-nav__dot" aria-hidden="true"></span><span>No platforms</span>';
      elements.platformSubNav.append(emptyItem);
      cacheSubNavSkeletonCount("platforms", 0);
      syncSidebarSubNavExpandedHeight(elements.platformSubNav);
      if (!state.platformsLoading) {
        clearBootSubNavSkeleton("platforms");
      }
      return;
    }

    for (const platform of nextPlatforms) {
      const platformId = normalizePlatformIdValue(platform.id);
      const isActive = platformId === state.selectedPlatformNavId;
      const button = document.createElement("button");
      button.type = "button";
      button.className = "super-admin-company-status-nav__item super-admin-platform-subnav__item";
      button.dataset.superAdminPlatformShortcut = platformId;
      button.setAttribute("aria-pressed", isActive ? "true" : "false");
      button.title = `${platform.name} - ${numberText(platform.businessTypeCount)} ${platform.businessTypeCount === 1 ? "business type" : "business types"}`;

      const dot = document.createElement("span");
      dot.className = "super-admin-company-status-nav__dot";
      dot.setAttribute("aria-hidden", "true");
      const label = document.createElement("span");
      label.textContent = platform.name;

      button.classList.toggle("is-active", isActive);
      button.append(dot, label);
      button.addEventListener("click", () => handlePlatformSubNavClick(platformId));
      elements.platformSubNav.append(button);
    }
    cacheSubNavSkeletonCount("platforms", nextPlatforms.length);
    syncSidebarSubNavExpandedHeight(elements.platformSubNav);
    if (!state.platformsLoading) {
      clearBootSubNavSkeleton("platforms");
    }
  }

  function normalizeHexColorValue(value, fallback = "#2563eb") {
    const normalized = String(value || "").trim().toLowerCase();
    return /^#[0-9a-f]{6}$/.test(normalized) ? normalized : fallback;
  }

  function getTakenPlatformColorMap(excludePlatformId = "") {
    const taken = new Map();
    const exclude = normalizePlatformIdValue(excludePlatformId);
    for (const platform of Array.isArray(state.platformDetails) ? state.platformDetails : []) {
      const id = normalizePlatformIdValue(platform.id);
      if (exclude && id === exclude) {
        continue;
      }
      const raw = String(platform.primaryColor || platform.color || platform.accentColor || "")
        .trim()
        .toLowerCase();
      if (!/^#[0-9a-f]{6}$/.test(raw) || taken.has(raw)) {
        continue;
      }
      taken.set(raw, String(platform.name || id || "another platform").trim() || "another platform");
    }
    return taken;
  }

  function getFirstAvailablePlatformPaletteColor(excludePlatformId = "") {
    const taken = getTakenPlatformColorMap(excludePlatformId);
    return platformPaletteColors.find((color) => !taken.has(color)) || "";
  }

  function getPlatformColorConflict(color, excludePlatformId = "") {
    const normalized = normalizeHexColorValue(color, "");
    if (!normalized) {
      return "";
    }
    return getTakenPlatformColorMap(excludePlatformId).get(normalized) || "";
  }

  function syncPlatformModalPrimaryColor(color, { force = false } = {}) {
    const normalized = normalizeHexColorValue(color, state.platformDraftPrimaryColor || "#2563eb");
    const owner = force ? "" : getPlatformColorConflict(normalized, state.editingPlatformId);
    if (owner) {
      setFeedback(`That color is already used by ${owner}. Each platform needs a unique color.`, "error");
      if (elements.platformPrimaryColorInput instanceof HTMLInputElement) {
        elements.platformPrimaryColorInput.value = state.platformDraftPrimaryColor;
      }
      if (elements.platformPrimaryColorHex) {
        elements.platformPrimaryColorHex.textContent = String(state.platformDraftPrimaryColor || "").toUpperCase();
      }
      return false;
    }
    state.platformDraftPrimaryColor = normalized;
    if (elements.platformPrimaryColorInput instanceof HTMLInputElement) {
      elements.platformPrimaryColorInput.value = normalized;
    }
    if (elements.platformPrimaryColorHex) {
      elements.platformPrimaryColorHex.textContent = normalized.toUpperCase();
    }
    if (elements.platformModalColorSwatches instanceof HTMLElement) {
      elements.platformModalColorSwatches.querySelectorAll("[data-platform-palette-swatch]").forEach((button) => {
        const swatch = String(button.dataset.platformPaletteSwatch || "").toLowerCase();
        const isSelected = swatch === normalized;
        button.classList.toggle("is-selected", isSelected);
        button.setAttribute("aria-pressed", String(isSelected));
      });
    }
    return true;
  }

  function renderPlatformModalColorSwatches() {
    if (!(elements.platformModalColorSwatches instanceof HTMLElement)) {
      return;
    }
    elements.platformModalColorSwatches.replaceChildren();
    const selected = normalizeHexColorValue(state.platformDraftPrimaryColor);
    const taken = getTakenPlatformColorMap(state.editingPlatformId);
    for (const color of platformPaletteColors) {
      const owner = taken.get(color) || "";
      const button = document.createElement("button");
      button.type = "button";
      button.className = "super-admin-platform-palette__swatch"
        + (color === selected ? " is-selected" : "")
        + (owner ? " is-taken" : "");
      button.style.backgroundColor = color;
      button.dataset.platformPaletteSwatch = color;
      button.disabled = Boolean(owner);
      button.setAttribute("aria-label", owner ? `${color} is already used by ${owner}` : `Select ${color}`);
      button.setAttribute("aria-pressed", String(color === selected));
      button.title = owner ? `Used by ${owner}` : color;
      button.addEventListener("click", () => {
        syncPlatformModalPrimaryColor(color);
      });
      elements.platformModalColorSwatches.append(button);
    }
  }

  async function loadPlatforms({ quiet = false } = {}) {
    const startedAt = Date.now();
    state.platformsLoading = true;
    renderPlatforms();
    if (!quiet) {
      setFeedback("Loading platforms...");
    }
    try {
      const response = await fetch("/api/super-admin/platforms", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to load platforms.");
      }

      const remain = SHOWCASE_SKELETON_MIN_MS - (Date.now() - startedAt);
      if (remain > 0) {
        await waitReportBoardMs(remain);
      }

      state.platformsLoading = false;
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : []);
      if (!quiet) {
        setFeedback(
          `${numberText(state.platformDetails.length)} ${state.platformDetails.length === 1 ? "platform" : "platforms"} loaded.`,
          "notice",
        );
      }
    } catch (error) {
      const remain = SHOWCASE_SKELETON_MIN_MS - (Date.now() - startedAt);
      if (remain > 0) {
        await waitReportBoardMs(remain);
      }
      state.platformsLoading = false;
      renderPlatforms();
      if (!quiet) {
        setFeedback(error instanceof Error ? error.message : "Unable to load platforms.", "error");
      }
    } finally {
      if (state.platformsLoading) {
        state.platformsLoading = false;
        renderPlatforms();
      }
      const pendingId = normalizePlatformIdValue(pendingPlatformFocusId);
      if (pendingId && state.activeSection === "platforms") {
        window.requestAnimationFrame(() => {
          focusPlatformShowcase(pendingId);
        });
      }
    }
  }

  function getEffectivePlatformIconName() {
    return normalizeLucideCategoryIconName(state.platformDraftIconName)
      || getAutoLucideCategoryIconName(elements.platformNameInput?.value)
      || "layout-grid";
  }

  function syncPlatformAssetFileNames() {
    if (elements.platformImageFileName) {
      elements.platformImageFileName.textContent = state.platformDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.platformDraftImageUrl, "No image selected");
    }
    if (elements.platformIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.platformDraftIconName);
      elements.platformIconFileName.textContent = state.platformDraftIconFile?.name
        || getBusinessTypeAssetFileName(
          state.platformDraftIconUrl,
          manualIconName ? `Art: ${formatLucideCategoryIconLabel(manualIconName)}` : "No 3D art selected",
        );
    }
  }

  function syncPlatformCreateRequiredMarks() {
    const isCreate = !state.editingPlatformId;
    document.querySelectorAll("[data-platform-create-required-mark]").forEach((mark) => {
      if (mark instanceof HTMLElement) {
        mark.hidden = !isCreate;
      }
    });
  }

  function syncPlatformModalToggles() {
    const isActive = elements.platformStatusSelect?.value !== "inactive";
    elements.platformStatusToggle?.classList.toggle("is-active", isActive);
    elements.platformStatusToggle?.setAttribute("aria-pressed", String(isActive));
    if (elements.platformStatusToggleLabel) {
      elements.platformStatusToggleLabel.textContent = isActive ? "Active" : "Inactive";
    }
    const platformRecord = getPlatformRecordById(state.editingPlatformId);
    const connectedBusinessTypeCount = state.editingPlatformId
      ? Math.max(
          Number(platformRecord?.businessTypeCount) || 0,
          getPlatformBusinessTypes(state.editingPlatformId).length,
        )
      : 0;
    const requiresComingSoon = connectedBusinessTypeCount === 0;
    if (requiresComingSoon && elements.platformComingSoonInput instanceof HTMLInputElement) {
      elements.platformComingSoonInput.checked = true;
    }
    const isAvailable = !Boolean(elements.platformComingSoonInput?.checked);
    elements.platformComingSoonToggle?.classList.toggle("is-active", isAvailable);
    elements.platformComingSoonToggle?.setAttribute("aria-pressed", String(isAvailable));
    if (elements.platformComingSoonToggle instanceof HTMLButtonElement) {
      elements.platformComingSoonToggle.disabled = requiresComingSoon;
      elements.platformComingSoonToggle.title = requiresComingSoon
        ? "Add a Business Type first to control Coming Soon."
        : "";
    }
    if (elements.platformComingSoonToggleLabel) {
      elements.platformComingSoonToggleLabel.textContent = isAvailable ? "Available" : "Coming Soon";
    }
    if (elements.platformComingSoonHelper instanceof HTMLElement) {
      elements.platformComingSoonHelper.hidden = !requiresComingSoon;
    }
  }

  function isSupportedPlatformAssetFile(file, type = "image") {
    if (!(file instanceof File)) {
      return false;
    }
    const fileType = String(file.type || "").toLowerCase();
    const fileName = String(file.name || "").toLowerCase();
    if (type === "icon") {
      return ["image/jpeg", "image/jpg", "image/png", "image/webp", "image/svg+xml", "image/gif"].includes(fileType)
        || /\.(jpe?g|png|webp|svg|gif)$/.test(fileName);
    }
    return ["image/jpeg", "image/jpg", "image/png", "image/webp"].includes(fileType)
      || /\.(jpe?g|png|webp)$/.test(fileName);
  }

  async function setPlatformAssetFile(type, file) {
    const isIcon = type === "icon";
    const input = isIcon ? elements.platformIconInput : elements.platformImageInput;
    const maxBytes = 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) state.platformDraftIconFile = null;
      else state.platformDraftImageFile = null;
      syncPlatformAssetFileNames();
      return;
    }
    if (!isSupportedPlatformAssetFile(file, type)) {
      setFeedback(isIcon
        ? "Choose a JPG, PNG, WEBP, SVG, or GIF platform 3D art file."
        : "Choose a JPG, PNG, or WEBP platform image.", "error");
      if (input) input.value = "";
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(isIcon ? "Platform 3D art must be 4MB or smaller." : "Platform image must be 4MB or smaller.", "error");
      if (input) input.value = "";
      return;
    }
    if (isIcon) {
      state.platformDraftIconFile = file;
      state.platformDraftIconName = "";
      state.platformDraftIconUrl = "";
    } else {
      state.platformDraftImageFile = file;
      state.platformDraftImageUrl = "";
    }
    syncPlatformAssetFileNames();
    setFeedback("");
  }

  async function uploadPlatformDraftAssets(platformDraft) {
    const nextDraft = { ...platformDraft };
    const pendingUploads = [];
    if (state.platformDraftImageFile instanceof File) {
      pendingUploads.push({ key: "heroImageUrl", label: "Uploading platform image...", file: state.platformDraftImageFile });
    }
    if (state.platformDraftIconFile instanceof File) {
      pendingUploads.push({ key: "iconImageUrl", label: "Uploading platform 3D art...", file: state.platformDraftIconFile });
    }
    if (pendingUploads.length) {
      const uploadedEntries = await mapWithConcurrency(
        pendingUploads,
        imageUploadConcurrency,
        async (entry) => {
          setFeedback(entry.label);
          return {
            key: entry.key,
            url: await uploadSuperAdminProductImageFile(entry.file, { preserveFormat: true }),
          };
        },
      );
      for (const entry of uploadedEntries) {
        nextDraft[entry.key] = entry.url;
      }
    }
    return nextDraft;
  }

  function setPlatformModalOpen(isOpen, { restoreFocus = true } = {}) {
    const overlay = elements.platformModalOverlay;
    if (!(overlay instanceof HTMLElement)) {
      return;
    }
    if (platformModalCloseTimer) {
      window.clearTimeout(platformModalCloseTimer);
      platformModalCloseTimer = 0;
    }
    if (platformModalFocusTimer) {
      window.clearTimeout(platformModalFocusTimer);
      platformModalFocusTimer = 0;
    }
    if (isOpen) {
      platformModalScrollSnapshot = getSuperAdminScrollSnapshot();
      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      elements.openPlatformModalButton?.setAttribute("aria-expanded", "true");
      window.requestAnimationFrame(() => overlay.classList.add("is-open"));
      platformModalFocusTimer = window.setTimeout(() => {
        platformModalFocusTimer = 0;
        if (elements.platformNameInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.platformNameInput);
          elements.platformNameInput.select();
        } else {
          focusWithoutScroll(elements.platformModal);
        }
        restoreSuperAdminScrollSnapshot(platformModalScrollSnapshot);
      }, 90);
      return;
    }
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    elements.openPlatformModalButton?.setAttribute("aria-expanded", "false");
    restoreSuperAdminScrollSnapshot(platformModalScrollSnapshot);
    platformModalCloseTimer = window.setTimeout(() => {
      platformModalCloseTimer = 0;
      overlay.hidden = true;
      if (restoreFocus) focusWithoutScroll(elements.openPlatformModalButton);
      restoreSuperAdminScrollSnapshotStable(platformModalScrollSnapshot);
      platformModalScrollSnapshot = null;
    }, 180);
  }

  function openPlatformModal(record = null) {
    const platform = normalizePlatformRecord(record) || {
      id: "",
      name: "",
      status: "active",
      sortOrder: (state.platformDetails.at(-1)?.sortOrder || 0) + 1,
      comingSoon: true,
      heroImageUrl: "",
      iconImageUrl: "",
      iconName: "",
      primaryColor: getFirstAvailablePlatformPaletteColor() || "#2563eb",
      secondaryColor: "",
    };
    state.editingPlatformId = platform.id || "";
    if (elements.platformModalTitle) {
      elements.platformModalTitle.textContent = state.editingPlatformId
        ? "Edit Platform Details"
        : "Add Platform Details";
    }
    if (elements.platformModalSubtitle) {
      elements.platformModalSubtitle.textContent = state.editingPlatformId
        ? `Update the details for ${platform.name}.`
        : "Add a new buyer platform by providing the details below.";
    }
    if (elements.platformNameInput) elements.platformNameInput.value = platform.name;
    if (elements.platformStatusSelect) {
      elements.platformStatusSelect.value = platform.status === "inactive" ? "inactive" : "active";
    }
    if (elements.platformComingSoonInput) {
      elements.platformComingSoonInput.checked = Boolean(platform.comingSoon);
    }
    state.platformDraftImageUrl = platform.heroImageUrl || "";
    state.platformDraftIconUrl = platform.iconImageUrl || "";
    state.platformDraftIconName = normalizeLucideCategoryIconName(platform.iconName);
    state.platformDraftPrimaryColor = normalizeHexColorValue(platform.primaryColor);
    state.platformDraftImageFile = null;
    state.platformDraftIconFile = null;
    if (elements.platformImageInput) elements.platformImageInput.value = "";
    if (elements.platformIconInput) elements.platformIconInput.value = "";
    if (elements.savePlatformButton) {
      elements.savePlatformButton.textContent = state.editingPlatformId ? "Save Platform" : "Add Platform";
    }
    syncPlatformAssetFileNames();
    syncPlatformModalToggles();
    syncPlatformCreateRequiredMarks();
    renderPlatformModalColorSwatches();
    syncPlatformModalPrimaryColor(state.platformDraftPrimaryColor, { force: true });
    setPlatformModalOpen(true);
  }

  function resetPlatformEditor() {
    state.editingPlatformId = "";
    if (elements.platformNameInput) elements.platformNameInput.value = "";
    if (elements.platformStatusSelect) elements.platformStatusSelect.value = "active";
    if (elements.platformComingSoonInput) elements.platformComingSoonInput.checked = true;
    state.platformDraftImageUrl = "";
    state.platformDraftIconUrl = "";
    state.platformDraftIconName = "";
    state.platformDraftPrimaryColor = getFirstAvailablePlatformPaletteColor() || "#2563eb";
    state.platformDraftImageFile = null;
    state.platformDraftIconFile = null;
    if (elements.platformImageInput) elements.platformImageInput.value = "";
    if (elements.platformIconInput) elements.platformIconInput.value = "";
    syncPlatformAssetFileNames();
    syncPlatformModalToggles();
    renderPlatformModalColorSwatches();
    syncPlatformModalPrimaryColor(state.platformDraftPrimaryColor, { force: true });
  }

  async function handleSavePlatform() {
    const name = String(elements.platformNameInput?.value || "").replace(/\s+/g, " ").trim();
    if (name.length < 2) {
      setFeedback("Enter a platform name first.", "error");
      elements.platformNameInput?.focus();
      return;
    }
    const isCreate = !state.editingPlatformId;
    const hasPhoto = state.platformDraftImageFile instanceof File
      || Boolean(normalizeBusinessTypeImageUrl(state.platformDraftImageUrl));
    const hasArt = state.platformDraftIconFile instanceof File
      || Boolean(normalizeBusinessTypeImageUrl(state.platformDraftIconUrl));
    if (isCreate && !hasPhoto) {
      setFeedback("Choose a platform image before creating.", "error");
      elements.platformImageInput?.closest("label")?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
      return;
    }
    if (isCreate && !hasArt) {
      setFeedback("Choose platform 3D art before creating.", "error");
      elements.platformIconInput?.closest("label")?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
      return;
    }
    const existing = state.editingPlatformId
      ? getPlatformRecordById(state.editingPlatformId)
      : null;
    const id = state.editingPlatformId || slugifyPlatformIdValue(name);
    const nextSortOrder = existing
      ? existing.sortOrder
      : ((state.platformDetails.at(-1)?.sortOrder || 0) + 1);
    const platformArtUrl = normalizeBusinessTypeImageUrl(state.platformDraftIconUrl);
    let payload = {
      name,
      id,
      status: elements.platformStatusSelect?.value === "inactive" ? "inactive" : "active",
      sortOrder: Number.isFinite(Number(nextSortOrder)) ? Math.trunc(Number(nextSortOrder)) : undefined,
      comingSoon: Boolean(elements.platformComingSoonInput?.checked),
      heroImageUrl: normalizeBusinessTypeImageUrl(state.platformDraftImageUrl),
      iconImageUrl: platformArtUrl,
      iconName: platformArtUrl
        ? ""
        : (normalizeLucideCategoryIconName(state.platformDraftIconName) || ""),
      primaryColor: normalizeHexColorValue(
        state.platformDraftPrimaryColor || existing?.primaryColor,
      ),
      secondaryColor: existing?.secondaryColor || "",
      storefrontMode: existing?.storefrontMode
        || resolvePlatformStorefrontMode(existing || {}, id),
    };

    const colorOwner = getPlatformColorConflict(payload.primaryColor, id);
    if (colorOwner) {
      setFeedback(`That color is already used by ${colorOwner}. Each platform needs a unique color.`, "error");
      return;
    }

    if (!await requireSuperAdminFingerprint(isCreate ? "add this platform" : "update this platform")) {
      return;
    }

    try {
      if (elements.savePlatformButton) elements.savePlatformButton.disabled = true;
      setFeedback(isCreate ? "Adding platform..." : "Updating platform...");
      payload = await uploadPlatformDraftAssets(payload);
      if (isCreate) {
        if (!normalizeBusinessTypeImageUrl(payload.heroImageUrl)) {
          throw new Error("Platform image is required.");
        }
        if (!normalizeBusinessTypeImageUrl(payload.iconImageUrl)) {
          throw new Error("Platform 3D art is required.");
        }
      }
      const response = await fetch("/api/super-admin/platforms", {
        method: isCreate ? "POST" : "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify(
          isCreate
            ? payload
            : { oldId: state.editingPlatformId, ...payload },
        ),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to save platform.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      resetPlatformEditor();
      setPlatformModalOpen(false, { restoreFocus: false });
      void showSuccessValidationModal(
        isCreate ? "Platform Added" : "Platform Updated",
        data.message || (isCreate ? "Platform added." : "Platform updated."),
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to save platform.", "error");
    } finally {
      if (elements.savePlatformButton) elements.savePlatformButton.disabled = false;
    }
  }

  async function handleReorderPlatform(platformId, direction) {
    const id = normalizePlatformIdValue(platformId);
    const index = state.platformDetails.findIndex((platform) => platform.id === id);
    if (index < 0) {
      return;
    }
    const swapIndex = direction === "up" ? index - 1 : index + 1;
    if (swapIndex < 0 || swapIndex >= state.platformDetails.length) {
      return;
    }
    if (!await requireSuperAdminFingerprint("reorder platforms")) {
      return;
    }
    const orderedIds = state.platformDetails.map((platform) => platform.id);
    const [moved] = orderedIds.splice(index, 1);
    orderedIds.splice(swapIndex, 0, moved);
    try {
      setFeedback("Updating platform order...");
      const response = await fetch("/api/super-admin/platforms", {
        method: "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify({ orderedIds }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to reorder platforms.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      void showSuccessValidationModal(
        "Platform Order Updated",
        data.message || "Home picker order updated.",
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to reorder platforms.", "error");
    }
  }

  async function handleSetPlatformStatus(platform, nextStatus) {
    const record = normalizePlatformRecord(platform);
    if (!record) return;
    const status = nextStatus === "inactive" ? "inactive" : "active";
    if (!await requireSuperAdminFingerprint(`${status === "active" ? "activate" : "deactivate"} this platform`)) {
      return;
    }
    try {
      setFeedback(status === "active" ? "Activating platform..." : "Deactivating platform...");
      const response = await fetch("/api/super-admin/platforms", {
        method: "PUT",
        headers: rootHeaders({ "Content-Type": "application/json", Accept: "application/json" }),
        body: JSON.stringify({ oldId: record.id, status }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to update platform status.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      void showSuccessValidationModal(
        status === "active" ? "Platform Activated" : "Platform Deactivated",
        data.message || `Platform ${status === "active" ? "activated" : "deactivated"}.`,
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to update platform status.", "error");
    }
  }

  async function handleDeletePlatform(platformId, platformName) {
    const id = normalizePlatformIdValue(platformId);
    if (!id) {
      return;
    }
    const confirmed = await openPlatformDeleteModal(platformName || id);
    if (!confirmed) {
      return;
    }
    if (!await requireSuperAdminFingerprint("delete this platform")) {
      return;
    }
    try {
      setFeedback("Deleting platform...");
      const response = await fetch(
        `/api/super-admin/platforms?id=${encodeURIComponent(id)}`,
        {
          method: "DELETE",
          headers: rootHeaders({ Accept: "application/json" }),
        },
      );
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to delete platform.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : []);
      void showSuccessValidationModal("Platform Deleted", data.message || "Platform deleted.");
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to delete platform.", "error");
    }
  }

  function normalizeStoreTypeRankingCompany(value, index = 0) {
    if (!value || typeof value !== "object") {
      return null;
    }
    const companyName = String(
      value.companyName || value.storeName || value.businessName || value.name || "",
    ).trim();
    const adminId = String(value.adminId || value.id || value.companyId || "").trim();
    if (!companyName && !adminId) {
      return null;
    }
    const productCount = Math.max(
      0,
      Math.trunc(normalizeStoreTypeNumber(value.productCount ?? value.items ?? value.count)),
    );
    const unitsSold = Math.max(
      0,
      Math.trunc(normalizeStoreTypeNumber(value.unitsSold ?? value.sold)),
    );
    const initials = String(value.initials || "")
      .trim()
      .toUpperCase()
      .slice(0, 3) ||
      companyName
        .split(/\s+/)
        .filter(Boolean)
        .slice(0, 2)
        .map((part) => part.charAt(0).toUpperCase())
        .join("") ||
      "CO";
    return {
      adminId,
      companyName: companyName || "Company",
      logoUrl: normalizeBusinessTypeImageUrl(
        value.logoUrl ?? value.imageUrl ?? value.avatarUrl ?? value.profileImageUrl,
      ),
      initials,
      productCount,
      unitsSold,
      score: Math.max(0, normalizeStoreTypeNumber(value.score)),
      rating: Math.max(0, Math.min(5, normalizeStoreTypeNumber(value.rating))),
      reviewCount: Math.max(
        0,
        Math.trunc(normalizeStoreTypeNumber(value.reviewCount ?? value.reviews ?? value.commentCount)),
      ),
      completedOrders: Math.max(
        0,
        Math.trunc(normalizeStoreTypeNumber(value.completedOrders)),
      ),
      avgFirstResponseHours: value.avgFirstResponseHours == null
        ? null
        : normalizeStoreTypeNumber(value.avgFirstResponseHours),
      timedReplies: Math.max(0, Math.trunc(normalizeStoreTypeNumber(value.timedReplies))),
      chats: Math.max(0, Math.trunc(normalizeStoreTypeNumber(value.chats ?? value.chatThreads))),
      cancelRate: Math.max(0, Math.min(1, normalizeStoreTypeNumber(value.cancelRate))),
      eligible: value.eligible === true,
      evaluating: value.evaluating === true
        || value.evaluation?.evaluating === true,
      evaluationRank: Math.max(
        1,
        Math.trunc(normalizeStoreTypeNumber(value.evaluationRank ?? index + 1)) || index + 1,
      ),
      daysRemaining: Math.max(
        0,
        Math.trunc(normalizeStoreTypeNumber(
          value.daysRemaining ?? value.evaluation?.daysRemaining,
        )),
      ),
      earlyScore: Math.max(
        0,
        normalizeStoreTypeNumber(value.earlyScore ?? value.score),
      ),
      breakdown: value.breakdown && typeof value.breakdown === "object"
        ? value.breakdown
        : null,
      rank: value.evaluating === true || value.evaluation?.evaluating === true
        ? 0
        : Math.max(1, Math.trunc(normalizeStoreTypeNumber(value.rank ?? index + 1)) || index + 1),
      createdAt: String(
        value.createdAt || value.created_at || value.registeredAt || value.dateCreated || "",
      ).trim(),
    };
  }

  function normalizeStoreTypeRankingItem(value, index = 0) {
    if (!value || typeof value !== "object") {
      return null;
    }
    const productId = String(value.productId || value.id || "").trim();
    const productName = String(value.productName || value.name || "").trim();
    if (!productId && !productName) {
      return null;
    }
    return {
      productId,
      productName: productName || "Unnamed item",
      imageUrl: normalizeBusinessTypeImageUrl(
        value.imageUrl ?? value.thumbnailUrl ?? value.photoUrl,
      ),
      adminId: String(value.adminId || "").trim(),
      companyName: String(value.companyName || value.storeName || value.sellerName || "").trim() ||
        "Company",
      companyLogoUrl: normalizeBusinessTypeImageUrl(
        value.companyLogoUrl ?? value.sellerLogoUrl ?? value.logoUrl,
      ),
      unitsSold: Math.max(
        0,
        Math.trunc(normalizeStoreTypeNumber(value.unitsSold ?? value.sold)),
      ),
      income: Math.max(0, normalizeStoreTypeNumber(value.income)),
      rating: Math.max(0, Math.min(5, normalizeStoreTypeNumber(value.rating))),
      ratingCount: Math.max(
        0,
        Math.trunc(normalizeStoreTypeNumber(value.ratingCount ?? value.reviewCount)),
      ),
      score: Math.max(0, normalizeStoreTypeNumber(value.score)),
      breakdown: value.breakdown && typeof value.breakdown === "object"
        ? value.breakdown
        : null,
      rank: Math.max(1, Math.trunc(normalizeStoreTypeNumber(value.rank ?? index + 1)) || index + 1),
      createdAt: String(
        value.createdAt
          || value.created_at
          || value.approvedAt
          || value.listedAt
          || value.dateCreated
          || "",
      ).trim(),
    };
  }

  function normalizeStoreTypeRankingList(values, normalizer) {
    const seen = new Set();
    const rows = [];
    for (const [index, value] of (Array.isArray(values) ? values : []).entries()) {
      const row = normalizer(value, index);
      if (!row) {
        continue;
      }
      const key = String(row.adminId || row.productId || `${row.companyName || row.productName}:${index}`)
        .trim()
        .toLowerCase();
      if (!key || seen.has(key)) {
        continue;
      }
      seen.add(key);
      rows.push(row);
      if (rows.length >= 10) {
        break;
      }
    }
    return rows;
  }

  function normalizeStoreTypeCompanyRanks(values) {
    const seen = new Set();
    const rows = [];
    for (const value of Array.isArray(values) ? values : []) {
      const adminId = String(value?.adminId || value?.id || value?.companyId || "").trim();
      const rank = Math.max(1, Math.trunc(normalizeStoreTypeNumber(value?.rank)) || 0);
      if (!adminId || rank < 1) {
        continue;
      }
      const key = adminId.toLowerCase();
      if (seen.has(key)) {
        continue;
      }
      seen.add(key);
      rows.push({ adminId, rank });
    }
    return rows;
  }

  function normalizeStoreTypeRecord(value) {
    const name = normalizeCategoryName(
      value && typeof value === "object"
        ? value.name ?? value.storeType ?? value.type ?? value.label ?? value.title
        : value,
    );

    if (!name) {
      return null;
    }

    const source = value && typeof value === "object" ? value : {};
    return {
      id: String(source.id ?? "").trim(),
      name,
      platformId: normalizePlatformIdValue(
        source.platformId ?? source.platform ?? source.buyerPlatform,
      ) || inferPlatformIdFromName(name),
      categories: normalizeCategoryValues(source.categories ?? source.category),
      status: normalizeStoreTypeStatus(source.status ?? source.businessTypeStatus),
      commissionRate: normalizeStoreTypeNumber(source.commissionRate ?? source.commission),
      serviceFee: normalizeStoreTypeNumber(source.serviceFee ?? source.serviceFeeAmount),
      companiesUsing: Math.trunc(normalizeStoreTypeNumber(source.companiesUsing)),
      productCount: Math.trunc(normalizeStoreTypeNumber(source.productCount)),
      topCompanies: normalizeStoreTypeRankingList(
        source.topCompanies ?? source.topContributors ?? source.rankedCompanies,
        normalizeStoreTypeRankingCompany,
      ),
      companyRanks: normalizeStoreTypeCompanyRanks(
        source.companyRanks ?? source.companyPlaces ?? source.rankedCompanyPlaces,
      ),
      evaluatingCompanies: normalizeStoreTypeRankingList(
        source.evaluatingCompanies ?? source.earlyCompanies ?? source.evaluationCompanies,
        normalizeStoreTypeRankingCompany,
      ),
      topItems: normalizeStoreTypeRankingList(
        source.topItems ?? source.topProducts ?? source.rankedItems,
        normalizeStoreTypeRankingItem,
      ),
      rankingLimit: Math.max(
        1,
        Math.trunc(normalizeStoreTypeNumber(source.rankingLimit)) || 10,
      ),
      rankingPreviewLimit: Math.max(
        1,
        Math.trunc(normalizeStoreTypeNumber(source.rankingPreviewLimit)) || 7,
      ),
      heroImageUrl: normalizeBusinessTypeImageUrl(
        source.heroImageUrl ?? source.imageUrl ?? source.coverImageUrl,
      ),
      iconImageUrl: normalizeBusinessTypeImageUrl(
        source.iconImageUrl ?? source.iconUrl ?? source.businessTypeIconUrl,
      ),
      iconName: normalizeLucideCategoryIconName(source.iconName ?? source.lucideIconName),
      categoryStats: normalizeStoreTypeCategoryStats(
        source.categoryStats ?? source.categoryDetails ?? source.categoryCounts,
      ),
    };
  }

  // Normalizes store type records before comparison or storage.
  function normalizeStoreTypeRecords(values) {
    const seen = new Map();
    for (const value of Array.isArray(values) ? values : []) {
      const record = normalizeStoreTypeRecord(value);
      if (!record) {
        continue;
      }
      const key = record.name.toLowerCase();
      if (!seen.has(key)) {
        seen.set(key, record);
      }
    }

    return [...seen.values()].sort((left, right) =>
      left.name.localeCompare(right.name, undefined, { sensitivity: "base" }),
    );
  }

  // Reads or derives store type record by name for the current super admin flow.
  function getStoreTypeRecordByName(storeTypeName) {
    const key = normalizeCategoryName(storeTypeName).toLowerCase();
    return state.storeTypeDetails.find((storeType) => storeType.name.toLowerCase() === key) || null;
  }

  // Formats store type percent for display.
  function formatStoreTypePercent(value) {
    return `${normalizeStoreTypeNumber(value).toFixed(2).replace(/\.00$/, "")}%`;
  }

  // Formats store type money for display.
  function formatStoreTypeMoney(value) {
    return `PHP ${normalizeStoreTypeNumber(value).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
  }

  // Checks whether same category name is true for the current record or UI state.
  function isSameCategoryName(left, right) {
    return normalizeCategoryName(left).toLowerCase() === normalizeCategoryName(right).toLowerCase();
  }

  // Checks whether same store type name is true for the current record or UI state.
  function isSameStoreTypeName(left, right) {
    return normalizeCategoryName(left).toLowerCase() === normalizeCategoryName(right).toLowerCase();
  }

  // Keeps category input casing synchronized with current state.
  function syncCategoryInputCasing(inputElement = elements.categoryNameInput) {
    if (!(inputElement instanceof HTMLInputElement)) {
      return;
    }

    const nextValue = normalizeCategoryName(inputElement.value, {
      preserveTrailingSpace: document.activeElement === inputElement,
    });
    if (inputElement.value !== nextValue) {
      inputElement.value = nextValue;
    }
  }

  // Keeps store type input casing synchronized with current state.
  function syncStoreTypeInputCasing(inputElement = elements.storeTypeNameInput) {
    if (!(inputElement instanceof HTMLInputElement)) {
      return;
    }

    const nextValue = normalizeCategoryName(inputElement.value, {
      preserveTrailingSpace: document.activeElement === inputElement,
    });
    if (inputElement.value !== nextValue) {
      inputElement.value = nextValue;
    }
  }

  // Updates store type modal tab and synchronizes related UI state.
  function setStoreTypeModalTab(tabName = "basic") {
    const normalizedTabName = String(tabName || "basic").trim();
    state.activeStoreTypeModalTab = normalizedTabName;

    for (const tabButton of elements.storeTypeModalTabs) {
      const isActive = tabButton.dataset.storeTypeModalTab === normalizedTabName;
      tabButton.classList.toggle("is-active", isActive);
      tabButton.setAttribute("aria-pressed", isActive ? "true" : "false");
    }

    for (const section of elements.storeTypeModalSections) {
      const isActive = section.dataset.storeTypeModalSection === normalizedTabName;
      section.hidden = !isActive;
      section.classList.toggle("is-active", isActive);
    }
  }

  // Renders store type draft categories from the latest state.
  function renderStoreTypeDraftCategories() {
    if (!elements.storeTypeCategoryChipList) {
      return;
    }

    if (elements.storeTypeCategoryCount) {
      elements.storeTypeCategoryCount.textContent = numberText(state.storeTypeDraftCategories.length);
    }
    elements.storeTypeCategoryChipList.innerHTML = "";
    if (!state.storeTypeDraftCategories.length) {
      const emptyState = document.createElement("div");
      emptyState.className = "empty-state super-admin-store-type-category-empty";
      emptyState.innerHTML = `${createLucideCategoryIconSvg("grid-2x2")}<span>No categories yet.</span>`;
      elements.storeTypeCategoryChipList.append(emptyState);
    } else {
      for (const categoryName of state.storeTypeDraftCategories) {
        const detail = state.storeTypeDraftCategoryDetails.find(
          (item) => isSameCategoryName(item.name, categoryName),
        ) || {};
        const chip = document.createElement("div");
        chip.className = "super-admin-store-type-category-chip super-admin-store-type-category-chip--visual";

        const visual = document.createElement("span");
        visual.className = "super-admin-store-type-category-chip__visual";
        if (detail.imageUrl) {
          const image = document.createElement("img");
          image.src = detail.imageUrl;
          image.alt = "";
          image.loading = "lazy";
          image.decoding = "async";
          visual.append(image);
        } else {
          visual.innerHTML = createIconSvg(
            '<rect width="18" height="18" x="3" y="3" rx="2" ry="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"></path>',
          );
        }

        const icon = document.createElement("span");
        icon.className = "super-admin-store-type-category-chip__icon";
        if (detail.iconImageUrl) {
          const iconImage = document.createElement("img");
          iconImage.src = detail.iconImageUrl;
          iconImage.alt = "";
          iconImage.loading = "lazy";
          iconImage.decoding = "async";
          icon.append(iconImage);
        } else {
          const selectedIconName = normalizeLucideCategoryIconName(detail.iconName)
            || getAutoLucideCategoryIconName(categoryName)
            || "tag";
          if (selectedIconName) {
            icon.classList.add("has-lucide-icon");
            icon.innerHTML = createLucideCategoryIconSvg(selectedIconName);
          } else {
            icon.classList.add("has-lucide-icon");
            icon.innerHTML = createLucideCategoryIconSvg("tag");
          }
        }

        const label = document.createElement("span");
        label.className = "super-admin-store-type-category-chip__label";
        label.textContent = categoryName;

        const editButton = document.createElement("button");
        editButton.type = "button";
        editButton.setAttribute("aria-label", `Edit ${categoryName}`);
        editButton.title = `Edit ${categoryName}`;
        editButton.innerHTML = createIconSvg('<path d="m4 20 4.2-1 9-9a2.1 2.1 0 0 0-3-3l-9 9L4 20Z"></path>');
        editButton.addEventListener("click", () => editStoreTypeDraftCategory(categoryName));

        const removeButton = document.createElement("button");
        removeButton.type = "button";
        removeButton.setAttribute("aria-label", `Remove ${categoryName}`);
        removeButton.innerHTML = createIconSvg(
          '<path d="M7 7 17 17" stroke-linecap="round"></path><path d="M17 7 7 17" stroke-linecap="round"></path>',
        );
        removeButton.addEventListener("click", () => {
          state.storeTypeDraftCategories = state.storeTypeDraftCategories.filter(
            (category) => !isSameCategoryName(category, categoryName),
          );
          state.storeTypeDraftCategoryDetails = state.storeTypeDraftCategoryDetails.filter(
            (item) => !isSameCategoryName(item.name, categoryName),
          );
          renderStoreTypeDraftCategories();
          syncStoreTypeModalSummary();
          if (isStoreTypeCategoryModalVisible() && normalizeCategoryName(state.categoryModalStoreTypeName)) {
            void handleSaveStoreTypeCategories({
              closeModal: false,
              includePendingCategory: false,
              successTitle: "Category Removed",
            });
          }
        });

        chip.append(visual, icon, label, editButton, removeButton);
        elements.storeTypeCategoryChipList.append(chip);
      }
    }

  }

  // Keep icon grids small on open. Rendering ~25% of Lucide+Tabler (~1.7k DOM
  // nodes) freezes the whole Super Admin when Add Business Type / Add Category opens.
  const ICON_PICKER_PAGE_SIZE = 48;

  function getIconPickerInitialVisibleCount(iconOptions) {
    const iconCount = Array.isArray(iconOptions) ? iconOptions.length : 0;
    return Math.min(iconCount, ICON_PICKER_PAGE_SIZE);
  }

  function getIconPickerVisibleCount(iconOptions, visibleCount) {
    const iconCount = Array.isArray(iconOptions) ? iconOptions.length : 0;
    const normalizedVisibleCount = Math.trunc(Number(visibleCount) || 0);
    if (normalizedVisibleCount > 0) {
      return Math.min(iconCount, normalizedVisibleCount);
    }
    return getIconPickerInitialVisibleCount(iconOptions);
  }

  function getIconPickerNextVisibleCount(iconOptions, visibleCount) {
    const iconCount = Array.isArray(iconOptions) ? iconOptions.length : 0;
    const currentVisibleCount = Math.max(0, Math.trunc(Number(visibleCount) || 0));
    return Math.min(iconCount, currentVisibleCount + ICON_PICKER_PAGE_SIZE);
  }

  function getIconPickerVisibleOptions(iconOptions, visibleCount, selectedIconName) {
    const visibleIconOptions = iconOptions.slice(0, visibleCount);
    const normalizedSelectedIconName = normalizeLucideCategoryIconName(selectedIconName);
    if (
      normalizedSelectedIconName &&
      !visibleIconOptions.some((option) => option.iconName === normalizedSelectedIconName)
    ) {
      const selectedOption = iconOptions.find((option) => option.iconName === normalizedSelectedIconName);
      if (selectedOption) {
        visibleIconOptions.unshift(selectedOption);
      }
    }
    return visibleIconOptions;
  }

  function getFilteredIconPickerOptions(searchTerm = "") {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    return getLucideCategoryIconOptions().filter((option) =>
      !normalizedSearchTerm
      || option.iconName.includes(normalizedSearchTerm)
      || normalizeLucideCategoryIconKey(option.label).includes(normalizedSearchTerm)
    );
  }

  function getPanelIconPickerVisibleCount(panel, iconOptions, searchTerm) {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    const previousSearchTerm = panel.dataset.businessTypeIconPickerSearchTerm || "";
    const storedVisibleCount = previousSearchTerm === normalizedSearchTerm
      ? Number.parseInt(panel.dataset.businessTypeIconPickerVisibleCount || "", 10)
      : 0;
    const visibleCount = getIconPickerVisibleCount(iconOptions, storedVisibleCount);
    panel.dataset.businessTypeIconPickerSearchTerm = normalizedSearchTerm;
    panel.dataset.businessTypeIconPickerVisibleCount = String(visibleCount);
    return visibleCount;
  }

  function setPanelIconPickerVisibleCount(panel, visibleCount) {
    panel.dataset.businessTypeIconPickerVisibleCount = String(Math.max(0, Math.trunc(Number(visibleCount) || 0)));
  }

  function setIconPickerCurrentSearchTerm(panel, searchTerm = "") {
    if (panel instanceof HTMLElement) {
      panel.dataset.businessTypeIconPickerCurrentSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    }
  }

  function getIconPickerSearchSurface(panel) {
    if (!(panel instanceof HTMLElement)) {
      return null;
    }
    if (panel.matches(".super-admin-store-type-category-modal__icon-grid")) {
      return panel;
    }
    return panel.querySelector(".business-type-showcase__icon-picker-grid");
  }

  function getIconPickerSearchInput(panel) {
    if (!(panel instanceof HTMLElement)) {
      return null;
    }
    if (panel.matches(".super-admin-store-type-category-modal__icon-grid")) {
      return panel.closest(".super-admin-store-type-category-modal__icon-picker")?.querySelector('input[type="search"]') || null;
    }
    return panel.querySelector(".business-type-showcase__icon-picker-search");
  }

  function scheduleIconPickerSearchRender(panel, render) {
    if (!(panel instanceof HTMLElement)) {
      render?.();
      return;
    }
    const existingTimer = iconPickerSearchRenderTimers.get(panel);
    if (existingTimer) {
      window.clearTimeout(existingTimer);
    }
    const searchInput = getIconPickerSearchInput(panel);
    const searchTerm = String(searchInput?.value || "").trim();
    if (!searchTerm) {
      iconPickerSearchRenderTimers.delete(panel);
      setSuperAdminSearchInputBusy(searchInput, false);
      render?.();
      return;
    }
    const searchSurface = getIconPickerSearchSurface(panel);
    setSuperAdminSearchInputBusy(searchInput, true);
    renderSuperAdminSearchState(searchSurface, {
      variant: "loading",
      message: "Searching icons...",
      compact: true,
    });
    const timer = window.setTimeout(() => {
      iconPickerSearchRenderTimers.delete(panel);
      setSuperAdminSearchInputBusy(searchInput, false);
      render?.();
    }, 260);
    iconPickerSearchRenderTimers.set(panel, timer);
  }

  function focusIconPickerSearchInput(panel) {
    const input = panel?.querySelector?.(".business-type-showcase__icon-picker-search");
    if (!(input instanceof HTMLInputElement)) {
      return;
    }
    input.focus({ preventScroll: true });
    const valueLength = input.value.length;
    input.setSelectionRange?.(valueLength, valueLength);
  }

  function isIconPickerSearchFocused(panel) {
    const activeElement = document.activeElement;
    return panel instanceof HTMLElement
      && activeElement instanceof HTMLInputElement
      && activeElement.classList.contains("business-type-showcase__icon-picker-search")
      && panel.contains(activeElement);
  }

  function hydrateIconPickerOptions(panel, visibleIconOptions, searchTerm, rerender) {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    setIconPickerCurrentSearchTerm(panel, searchTerm);
    const visibleTablerIconNames = visibleIconOptions
      .map((option) => option.iconName)
      .filter((iconName) => getTablerIconSlug(iconName));
    const needsCatalog = Boolean(normalizedSearchTerm) && hasUndiscoveredTablerIcons();
    const needsPaths = visibleTablerIconNames.some((iconName) => !getTablerIconPathFromCache(getTablerIconSlug(iconName)));
    if (!needsCatalog && !needsPaths) {
      return;
    }
    const hydrateToken = String(++iconPickerHydrateTokenCounter);
    panel.dataset.businessTypeIconPickerHydrateToken = hydrateToken;
    Promise.all([
      needsCatalog ? ensureTablerIconCatalog() : Promise.resolve(),
      needsPaths ? ensureTablerIconPaths(visibleTablerIconNames) : Promise.resolve(),
    ])
      .then(() => {
        if (
          panel.isConnected
          && panel.dataset.businessTypeIconPickerHydrateToken === hydrateToken
          && panel.dataset.businessTypeIconPickerCurrentSearchTerm === normalizedSearchTerm
        ) {
          rerender?.();
        }
      })
      .catch(() => {
        // Search still works with available Lucide icons if the optional Tabler catalog cannot be read.
      });
  }

  function createIconPickerShowMoreButton(hiddenCount, onClick) {
    const showMoreButton = document.createElement("button");
    showMoreButton.type = "button";
    showMoreButton.className = "super-admin-store-type-category-modal__icon-show-more";
    showMoreButton.textContent = hiddenCount > 0 ? `Show more (${numberText(hiddenCount)})` : "Show more";
    showMoreButton.addEventListener("click", () => {
      void onClick?.();
    });
    return showMoreButton;
  }

  function renderStoreTypeCategoryIconPicker() {
    if (!elements.storeTypeCategoryIconPicker) {
      return;
    }

    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
    const searchTerm = String(state.storeTypeCategoryIconSearchTerm || "").trim().toLowerCase();
    setIconPickerCurrentSearchTerm(elements.storeTypeCategoryIconPicker, searchTerm);
    const iconOptions = getFilteredIconPickerOptions(searchTerm);
    const iconFragment = document.createDocumentFragment();
    elements.storeTypeCategoryIconPicker.innerHTML = "";
    elements.storeTypeCategoryIconPicker.classList.remove("has-super-admin-search-state");
    const visibleCount = getIconPickerVisibleCount(iconOptions, state.storeTypeCategoryIconVisibleCount);
    const visibleIconOptions = getIconPickerVisibleOptions(iconOptions, visibleCount, manualIconName);

    const autoButton = document.createElement("button");
    autoButton.type = "button";
    autoButton.className = "super-admin-store-type-category-modal__icon-option";
    autoButton.classList.toggle("is-selected", !manualIconName);
    autoButton.setAttribute("aria-pressed", String(!manualIconName));
    autoButton.setAttribute("aria-label", "Use automatic category icon");
    autoButton.dataset.storeTypeCategoryIconAutoOption = "";
    autoButton.title = "Auto";
    autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    autoButton.addEventListener("click", () => {
      state.storeTypeCategoryDraftIconName = "";
      state.storeTypeCategoryDraftIconNameTouched = true;
      renderStoreTypeCategoryIconPicker();
      syncStoreTypeCategoryAssetFileNames();
    });
    if (!searchTerm || iconOptions.length) {
      iconFragment.append(autoButton);
    }

    for (const { iconName, label } of visibleIconOptions) {
      const iconButton = document.createElement("button");
      iconButton.type = "button";
      iconButton.className = "super-admin-store-type-category-modal__icon-option";
      const isSelected = manualIconName === iconName;
      iconButton.classList.toggle("is-selected", isSelected);
      iconButton.setAttribute("aria-pressed", String(isSelected));
      iconButton.setAttribute("aria-label", `Use ${label} icon`);
      iconButton.title = label;
      iconButton.innerHTML = createLucideCategoryIconSvg(iconName, { queueTablerRefresh: false });
      iconButton.addEventListener("click", () => {
        state.storeTypeCategoryDraftIconName = iconName;
        state.storeTypeCategoryDraftIconNameTouched = true;
        renderStoreTypeCategoryIconPicker();
        syncStoreTypeCategoryAssetFileNames();
      });
      iconFragment.append(iconButton);
    }
    if (visibleCount < iconOptions.length || hasUndiscoveredTablerIcons()) {
      iconFragment.append(createIconPickerShowMoreButton(Math.max(iconOptions.length - visibleCount, 0), async () => {
        await ensureTablerIconCatalog();
        const nextIconOptions = getFilteredIconPickerOptions(searchTerm);
        state.storeTypeCategoryIconVisibleCount = getIconPickerNextVisibleCount(nextIconOptions, visibleCount);
        renderStoreTypeCategoryIconPicker();
      }));
    }
    if (!iconOptions.length) {
      iconFragment.append(createSuperAdminSearchState({
        variant: "empty",
        message: "No icons match your search.",
        compact: true,
        className: "super-admin-store-type-category-modal__icon-empty",
      }));
    }
    elements.storeTypeCategoryIconPicker.append(iconFragment);
    hydrateIconPickerOptions(elements.storeTypeCategoryIconPicker, visibleIconOptions, searchTerm, () => {
      renderStoreTypeCategoryIconPicker();
    });

    syncStoreTypeCategoryIconPickerSummary();
  }

  function syncStoreTypeCategoryIconPickerSummary() {
    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
    const autoButton = elements.storeTypeCategoryIconPicker?.querySelector("[data-store-type-category-icon-auto-option]");
    if (autoButton instanceof HTMLButtonElement) {
      autoButton.classList.toggle("is-selected", !manualIconName);
      autoButton.setAttribute("aria-pressed", String(!manualIconName));
      autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    }
    if (elements.storeTypeCategorySelectedIconName) {
      elements.storeTypeCategorySelectedIconName.textContent = manualIconName
        ? formatLucideCategoryIconLabel(manualIconName)
        : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)}`;
    }
  }

  function getEffectiveStoreTypeIconName() {
    return normalizeLucideCategoryIconName(state.storeTypeDraftIconName)
      || getAutoLucideCategoryIconName(elements.storeTypeNameInput?.value)
      || "store";
  }

  function renderStoreTypeIconPicker() {
    if (!elements.storeTypeIconPicker) {
      return;
    }

    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeIconName();
    const searchTerm = String(state.storeTypeIconSearchTerm || "").trim().toLowerCase();
    setIconPickerCurrentSearchTerm(elements.storeTypeIconPicker, searchTerm);
    const iconOptions = getFilteredIconPickerOptions(searchTerm);
    const iconFragment = document.createDocumentFragment();
    elements.storeTypeIconPicker.innerHTML = "";
    elements.storeTypeIconPicker.classList.remove("has-super-admin-search-state");
    const visibleCount = getIconPickerVisibleCount(iconOptions, state.storeTypeIconVisibleCount);
    const visibleIconOptions = getIconPickerVisibleOptions(iconOptions, visibleCount, manualIconName);

    const autoButton = document.createElement("button");
    autoButton.type = "button";
    autoButton.className = "super-admin-store-type-category-modal__icon-option";
    autoButton.classList.toggle("is-selected", !manualIconName);
    autoButton.setAttribute("aria-pressed", String(!manualIconName));
    autoButton.setAttribute("aria-label", "Use automatic business type icon");
    autoButton.dataset.storeTypeIconAutoOption = "";
    autoButton.title = "Auto";
    autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    autoButton.addEventListener("click", () => {
      state.storeTypeDraftIconName = "";
      state.storeTypeDraftIconFile = null;
      state.storeTypeDraftIconUrl = "";
      if (elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      }
      renderStoreTypeIconPicker();
      syncStoreTypeAssetFileNames();
    });
    if (!searchTerm || iconOptions.length) {
      iconFragment.append(autoButton);
    }

    for (const { iconName, label } of visibleIconOptions) {
      const iconButton = document.createElement("button");
      iconButton.type = "button";
      iconButton.className = "super-admin-store-type-category-modal__icon-option";
      const isSelected = manualIconName === iconName;
      iconButton.classList.toggle("is-selected", isSelected);
      iconButton.setAttribute("aria-pressed", String(isSelected));
      iconButton.setAttribute("aria-label", `Use ${label} icon`);
      iconButton.title = label;
      iconButton.innerHTML = createLucideCategoryIconSvg(iconName, { queueTablerRefresh: false });
      iconButton.addEventListener("click", () => {
        state.storeTypeDraftIconName = iconName;
        state.storeTypeDraftIconFile = null;
        state.storeTypeDraftIconUrl = "";
        if (elements.storeTypeIconInput) {
          elements.storeTypeIconInput.value = "";
        }
        renderStoreTypeIconPicker();
        syncStoreTypeAssetFileNames();
      });
      iconFragment.append(iconButton);
    }

    if (visibleCount < iconOptions.length || hasUndiscoveredTablerIcons()) {
      iconFragment.append(createIconPickerShowMoreButton(Math.max(iconOptions.length - visibleCount, 0), async () => {
        await ensureTablerIconCatalog();
        const nextIconOptions = getFilteredIconPickerOptions(searchTerm);
        state.storeTypeIconVisibleCount = getIconPickerNextVisibleCount(nextIconOptions, visibleCount);
        renderStoreTypeIconPicker();
      }));
    }

    if (!iconOptions.length) {
      iconFragment.append(createSuperAdminSearchState({
        variant: "empty",
        message: "No icons match your search.",
        compact: true,
        className: "super-admin-store-type-category-modal__icon-empty",
      }));
    }
    elements.storeTypeIconPicker.append(iconFragment);
    hydrateIconPickerOptions(elements.storeTypeIconPicker, visibleIconOptions, searchTerm, () => {
      renderStoreTypeIconPicker();
    });
    syncStoreTypeIconPickerSummary();
  }

  function syncStoreTypeIconPickerSummary() {
    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeIconName();
    const autoButton = elements.storeTypeIconPicker?.querySelector("[data-store-type-icon-auto-option]");
    if (autoButton instanceof HTMLButtonElement) {
      autoButton.classList.toggle("is-selected", !manualIconName);
      autoButton.setAttribute("aria-pressed", String(!manualIconName));
      autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    }
    if (elements.storeTypeSelectedIconName) {
      elements.storeTypeSelectedIconName.textContent = manualIconName
        ? formatLucideCategoryIconLabel(manualIconName)
        : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)}`;
    }
  }

  function syncStoreTypeCategoryAssetFileNames() {
    if (elements.storeTypeCategoryImageFileName) {
      elements.storeTypeCategoryImageFileName.textContent = state.storeTypeCategoryDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeCategoryDraftImageUrl, "No image selected");
    }
    if (elements.storeTypeCategoryIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
      const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
      elements.storeTypeCategoryIconFileName.textContent = state.storeTypeCategoryDraftIconFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeCategoryDraftIconUrl, "No icon selected");
      if (
        !state.storeTypeCategoryDraftIconFile
        && !state.storeTypeCategoryDraftIconUrl
      ) {
        elements.storeTypeCategoryIconFileName.textContent = manualIconName
          ? `${formatLucideCategoryIconLabel(manualIconName)} icon`
          : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)} icon`;
      }
    }
  }

  function resetStoreTypeCategoryComposer({ focusInput = false } = {}) {
    state.editingStoreTypeCategoryName = "";
    state.storeTypeCategoryDraftImageUrl = "";
    state.storeTypeCategoryDraftIconUrl = "";
    state.storeTypeCategoryDraftIconName = "";
    state.storeTypeCategoryDraftIconNameTouched = false;
    state.storeTypeCategoryDraftImageFile = null;
    state.storeTypeCategoryDraftIconFile = null;
    state.storeTypeCategoryIconSearchTerm = "";
    state.storeTypeCategoryIconVisibleCount = 0;
    if (elements.storeTypeCategoryInput) elements.storeTypeCategoryInput.value = "";
    if (elements.storeTypeCategoryIconSearchInput) elements.storeTypeCategoryIconSearchInput.value = "";
    if (elements.storeTypeCategoryImageInput) elements.storeTypeCategoryImageInput.value = "";
    if (elements.storeTypeCategoryIconInput) elements.storeTypeCategoryIconInput.value = "";
    if (elements.addStoreTypeCategoryButton) elements.addStoreTypeCategoryButton.textContent = "Add Category";
    renderStoreTypeCategoryIconPicker();
    syncStoreTypeCategoryAssetFileNames();
    if (focusInput) elements.storeTypeCategoryInput?.focus();
  }

  function editStoreTypeDraftCategory(categoryName) {
    const detail = state.storeTypeDraftCategoryDetails.find(
      (item) => isSameCategoryName(item.name, categoryName),
    ) || {};
    state.editingStoreTypeCategoryName = categoryName;
    state.storeTypeCategoryDraftImageUrl = normalizeBusinessTypeImageUrl(detail.imageUrl);
    state.storeTypeCategoryDraftIconUrl = normalizeBusinessTypeImageUrl(detail.iconImageUrl);
    state.storeTypeCategoryDraftIconName = normalizeLucideCategoryIconName(detail.iconName);
    state.storeTypeCategoryDraftIconNameTouched = false;
    state.storeTypeCategoryDraftImageFile = null;
    state.storeTypeCategoryDraftIconFile = null;
    state.storeTypeCategoryIconVisibleCount = 0;
    if (elements.storeTypeCategoryInput) elements.storeTypeCategoryInput.value = categoryName;
    if (elements.addStoreTypeCategoryButton) elements.addStoreTypeCategoryButton.textContent = "Update Category";
    renderStoreTypeCategoryIconPicker();
    syncStoreTypeCategoryAssetFileNames();
    elements.storeTypeCategoryInput?.focus();
    elements.storeTypeCategoryInput?.select();
  }

  // Supports the add store type draft category branch of the super admin UI.
  function addStoreTypeDraftCategory({ focusInput = true } = {}) {
    const categoryName = normalizeCategoryName(elements.storeTypeCategoryInput?.value);
    if (!categoryName) {
      elements.storeTypeCategoryInput?.focus();
      return false;
    }

    if (!state.storeTypeDraftCategories.some((category) => isSameCategoryName(category, categoryName))) {
      state.storeTypeDraftCategories = normalizeCategoryValues([
        ...state.storeTypeDraftCategories,
        categoryName,
      ]);
    }

    const previousName = state.editingStoreTypeCategoryName || categoryName;
    const existingDetail = state.storeTypeDraftCategoryDetails.find(
      (item) => isSameCategoryName(item.name, previousName),
    ) || {};
    state.storeTypeDraftCategoryDetails = [
      ...state.storeTypeDraftCategoryDetails.filter(
        (item) => !isSameCategoryName(item.name, previousName) && !isSameCategoryName(item.name, categoryName),
      ),
      {
        name: categoryName,
        productCount: Math.trunc(normalizeStoreTypeNumber(existingDetail.productCount)),
        imageUrl: state.storeTypeCategoryDraftImageUrl || existingDetail.imageUrl || "",
        iconImageUrl: state.storeTypeCategoryDraftIconUrl || existingDetail.iconImageUrl || "",
        iconName: state.storeTypeCategoryDraftIconNameTouched
          ? normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName)
          : normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName)
            || normalizeLucideCategoryIconName(existingDetail.iconName),
        status: normalizeStoreTypeCategoryStatus(existingDetail.status),
        imageFile: state.storeTypeCategoryDraftImageFile,
        iconFile: state.storeTypeCategoryDraftIconFile,
      },
    ];
    if (state.editingStoreTypeCategoryName && !isSameCategoryName(state.editingStoreTypeCategoryName, categoryName)) {
      state.storeTypeDraftCategories = state.storeTypeDraftCategories.map((item) =>
        isSameCategoryName(item, state.editingStoreTypeCategoryName) ? categoryName : item,
      );
    }
    state.storeTypeDraftCategories = normalizeCategoryValues(state.storeTypeDraftCategories);
    renderStoreTypeDraftCategories();
    syncStoreTypeModalSummary();
    resetStoreTypeCategoryComposer({ focusInput });
    return true;
  }

  function getBusinessTypeAssetFileName(value, fallback = "") {
    const normalizedUrl = String(value || "").trim().split("#")[0].split("?")[0];
    const fileName = normalizedUrl.split(/[\\/]/).pop() || "";
    if (!fileName) {
      return fallback;
    }
    try {
      return decodeURIComponent(fileName);
    } catch (error) {
      return fileName;
    }
  }

  function syncStoreTypeAssetFileNames() {
    if (elements.storeTypeImageFileName) {
      elements.storeTypeImageFileName.textContent = state.storeTypeDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeDraftImageUrl, "No image selected");
    }
    if (elements.storeTypeIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
      elements.storeTypeIconFileName.textContent = state.storeTypeDraftIconFile?.name
        || getBusinessTypeAssetFileName(
          state.storeTypeDraftIconUrl,
          manualIconName ? `Icon: ${formatLucideCategoryIconLabel(manualIconName)}` : "No icon selected",
        );
    }
    syncStoreTypeIconPickerSummary();
  }

  function syncStoreTypeStatusOptions() {
    const selectedStatus = normalizeStoreTypeStatus(elements.storeTypeStatusSelect?.value);
    const isActive = selectedStatus === "active";
    elements.storeTypeStatusToggle?.classList.toggle("is-active", isActive);
    elements.storeTypeStatusToggle?.setAttribute("aria-pressed", isActive ? "true" : "false");
    if (elements.storeTypeStatusToggleLabel) {
      elements.storeTypeStatusToggleLabel.textContent = isActive ? "Active" : "Inactive";
    }
  }

  function isSupportedBusinessTypeAssetFile(file, type = "image") {
    if (!(file instanceof File)) {
      return false;
    }
    const fileType = String(file.type || "").toLowerCase();
    const fileName = String(file.name || "").toLowerCase();
    if (type === "icon") {
      return ["image/png", "image/svg+xml"].includes(fileType) || /\.(png|svg)$/.test(fileName);
    }
    return ["image/jpeg", "image/jpg", "image/png", "image/webp"].includes(fileType)
      || /\.(jpe?g|png|webp)$/.test(fileName);
  }

  async function setStoreTypeAssetFile(type, file) {
    const isIcon = type === "icon";
    const maxBytes = isIcon ? 2 * 1024 * 1024 : 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) {
        state.storeTypeDraftIconFile = null;
      } else {
        state.storeTypeDraftImageFile = null;
      }
      syncStoreTypeAssetFileNames();
      return;
    }
    if (!isSupportedBusinessTypeAssetFile(file, type)) {
      setFeedback(
        isIcon ? "Choose a PNG or SVG icon." : "Choose a JPG, PNG, or WEBP image.",
        "error",
      );
      if (isIcon && elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      } else if (!isIcon && elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(
        isIcon ? "Business type icon must be 2MB or smaller." : "Business type image must be 4MB or smaller.",
        "error",
      );
      if (isIcon && elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      } else if (!isIcon && elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      return;
    }

    let preparedFile = file;
    if (!isIcon) {
      preparedFile = await prepareSquareImageUploadFile(file, {
        title: "Crop business type image",
        copy: "Square photos are used as-is. Wider or taller photos can be cropped to a square.",
      });
      if (elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      if (!(preparedFile instanceof File)) {
        return;
      }
    }

    if (isIcon) {
      state.storeTypeDraftIconFile = preparedFile;
      state.storeTypeDraftIconName = "";
      renderStoreTypeIconPicker();
    } else {
      state.storeTypeDraftImageFile = preparedFile;
    }
    syncStoreTypeAssetFileNames();
    setFeedback("");
  }

  async function setStoreTypeCategoryAssetFile(type, file) {
    const isIcon = type === "icon";
    const input = isIcon ? elements.storeTypeCategoryIconInput : elements.storeTypeCategoryImageInput;
    const maxBytes = isIcon ? 2 * 1024 * 1024 : 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) state.storeTypeCategoryDraftIconFile = null;
      else state.storeTypeCategoryDraftImageFile = null;
      syncStoreTypeCategoryAssetFileNames();
      return;
    }
    if (!isSupportedBusinessTypeAssetFile(file, type)) {
      setFeedback(isIcon ? "Choose a PNG or SVG category icon." : "Choose a JPG, PNG, or WEBP category image.", "error");
      if (input) input.value = "";
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(isIcon ? "Category icon must be 2MB or smaller." : "Category image must be 4MB or smaller.", "error");
      if (input) input.value = "";
      return;
    }
    let preparedFile = file;
    if (!isIcon) {
      preparedFile = await prepareSquareImageUploadFile(file, {
        title: "Crop category image",
        copy: "Square photos are used as-is. Wider or taller photos can be cropped to a square.",
      });
      if (input) input.value = "";
      if (!(preparedFile instanceof File)) {
        return;
      }
    }
    if (isIcon) state.storeTypeCategoryDraftIconFile = preparedFile;
    else state.storeTypeCategoryDraftImageFile = preparedFile;
    syncStoreTypeCategoryAssetFileNames();
    setFeedback("");
  }

  async function uploadStoreTypeCategoryDetails() {
    const detailsWithFiles = state.storeTypeDraftCategoryDetails.map((detail, index) => ({
      detail,
      index,
    }));
    const uploadedFilePairs = await mapWithConcurrency(
      detailsWithFiles.filter(({ detail }) =>
        detail.imageFile instanceof File || detail.iconFile instanceof File,
      ),
      imageUploadConcurrency,
      async ({ detail, index }) => {
        const uploads = {};
        if (detail.imageFile instanceof File) {
          setFeedback(`Uploading image for ${detail.name}...`);
          uploads.imageUrl = await uploadSuperAdminProductImageFile(detail.imageFile);
        }
        if (detail.iconFile instanceof File) {
          setFeedback(`Uploading icon for ${detail.name}...`);
          uploads.iconImageUrl = await uploadSuperAdminProductImageFile(detail.iconFile);
        }
        return { index, uploads };
      },
    );
    const uploadByIndex = new Map(uploadedFilePairs.map((entry) => [entry.index, entry.uploads]));
    const uploadedDetails = [];
    for (const [index, detail] of state.storeTypeDraftCategoryDetails.entries()) {
      const nextDetail = {
        name: detail.name,
        productCount: Math.trunc(normalizeStoreTypeNumber(detail.productCount)),
        imageUrl: normalizeBusinessTypeImageUrl(detail.imageUrl),
        iconImageUrl: normalizeBusinessTypeImageUrl(detail.iconImageUrl),
        iconName: normalizeLucideCategoryIconName(detail.iconName),
        status: normalizeStoreTypeCategoryStatus(detail.status),
      };
      const uploads = uploadByIndex.get(index);
      if (uploads?.imageUrl) {
        nextDetail.imageUrl = uploads.imageUrl;
      }
      if (uploads?.iconImageUrl) {
        nextDetail.iconImageUrl = uploads.iconImageUrl;
      }
      uploadedDetails.push(nextDetail);
    }
    return uploadedDetails;
  }

  async function uploadStoreTypeDraftAssets(storeTypeDraft) {
    const nextDraft = { ...storeTypeDraft };
    const pendingUploads = [];
    if (state.storeTypeDraftImageFile instanceof File) {
      pendingUploads.push({
        key: "heroImageUrl",
        label: "Uploading business type image...",
        file: state.storeTypeDraftImageFile,
      });
    }
    if (state.storeTypeDraftIconFile instanceof File) {
      pendingUploads.push({
        key: "iconImageUrl",
        label: "Uploading business type icon...",
        file: state.storeTypeDraftIconFile,
      });
    }
    if (pendingUploads.length) {
      const uploadedEntries = await mapWithConcurrency(
        pendingUploads,
        imageUploadConcurrency,
        async (entry) => {
          setFeedback(entry.label);
          return {
            key: entry.key,
            url: await uploadSuperAdminProductImageFile(entry.file),
          };
        },
      );
      for (const entry of uploadedEntries) {
        nextDraft[entry.key] = entry.url;
      }
    }
    return nextDraft;
  }

  // Reads or derives current store type draft for the current super admin flow.
  function getCurrentStoreTypeDraft() {
    const selectedRecord = getStoreTypeRecordByName(
      normalizeCategoryName(elements.storeTypeNameInput?.value) || state.editingStoreTypeName,
    );
    const hasIconImage = state.storeTypeDraftIconFile instanceof File || Boolean(state.storeTypeDraftIconUrl);
    const categories = [...state.storeTypeDraftCategories];
    return {
      name: normalizeCategoryName(elements.storeTypeNameInput?.value),
      platformId: normalizePlatformIdValue(elements.storeTypePlatformSelect?.value) || "shop",
      categories,
      // Persist Super Admin category photos/icons with the business type save.
      categoryDetails: getStoreTypeCategoryDetailsForSave(
        {
          categories,
          categoryStats: state.storeTypeDraftCategoryDetails,
        },
        categories,
      ),
      status: normalizeStoreTypeStatus(elements.storeTypeStatusSelect?.value),
      commissionRate: normalizeStoreTypeNumber(elements.storeTypeCommissionRateInput?.value),
      serviceFee: normalizeStoreTypeNumber(elements.storeTypeServiceFeeInput?.value),
      heroImageUrl: normalizeBusinessTypeImageUrl(state.storeTypeDraftImageUrl),
      iconImageUrl: normalizeBusinessTypeImageUrl(state.storeTypeDraftIconUrl),
      iconName: hasIconImage
        ? normalizeLucideCategoryIconName(state.storeTypeDraftIconName)
        : (
            normalizeLucideCategoryIconName(state.storeTypeDraftIconName || selectedRecord?.iconName)
            || getEffectiveStoreTypeIconName()
          ),
      companiesUsing: Math.trunc(normalizeStoreTypeNumber(selectedRecord?.companiesUsing)),
      productCount: Math.trunc(normalizeStoreTypeNumber(selectedRecord?.productCount)),
    };
  }

  // Keeps store type modal summary synchronized with current state.
  function syncStoreTypeModalSummary() {
    const draft = getCurrentStoreTypeDraft();
    const isEditing = Boolean(state.editingStoreTypeName);
    if (elements.storeTypeModalTitle) {
      elements.storeTypeModalTitle.textContent = isEditing
        ? "Edit Business Type Details"
        : "Add Business Type Details";
    }
    if (elements.storeTypeModalSubtitle) {
      elements.storeTypeModalSubtitle.textContent = isEditing
        ? `Update the details for ${draft.name || state.editingStoreTypeName}.`
        : "Add a new business type by providing the details below.";
    }
    syncStoreTypeStatusOptions();
    syncStoreTypeAssetFileNames();
  }

  // Supports the populate store type modal branch of the super admin UI.
  function populateStoreTypeModal(record = null) {
    const storeType = normalizeStoreTypeRecord(record) || {
      name: "",
      platformId: "shop",
      categories: [],
      status: "active",
      commissionRate: 0,
      serviceFee: 0,
      companiesUsing: 0,
      productCount: 0,
      heroImageUrl: "",
      iconImageUrl: "",
    };

    if (elements.storeTypeNameInput) {
      elements.storeTypeNameInput.value = storeType.name;
    }
    syncStoreTypePlatformSelect(storeType.platformId || "shop");
    if (elements.storeTypeStatusSelect) {
      elements.storeTypeStatusSelect.value = storeType.status;
    }
    if (elements.storeTypeCommissionRateInput) {
      elements.storeTypeCommissionRateInput.value = storeType.commissionRate ? String(storeType.commissionRate) : "";
    }
    if (elements.storeTypeServiceFeeInput) {
      elements.storeTypeServiceFeeInput.value = storeType.serviceFee ? String(storeType.serviceFee) : "";
    }

    state.storeTypeDraftImageUrl = storeType.heroImageUrl;
    state.storeTypeDraftIconUrl = storeType.iconImageUrl;
    state.storeTypeDraftIconName = normalizeLucideCategoryIconName(storeType.iconName);
    state.storeTypeIconSearchTerm = "";
    state.storeTypeIconVisibleCount = 0;
    state.storeTypeDraftImageFile = null;
    state.storeTypeDraftIconFile = null;
    if (elements.storeTypeImageInput) {
      elements.storeTypeImageInput.value = "";
    }
    if (elements.storeTypeIconInput) {
      elements.storeTypeIconInput.value = "";
    }

    state.storeTypeDraftCategories = [...storeType.categories];
    state.storeTypeDraftCategoryDetails = (storeType.categoryStats || []).map((detail) => ({
      ...detail,
    }));
    renderStoreTypeDraftCategories();
    if (elements.storeTypeIconSearchInput) {
      elements.storeTypeIconSearchInput.value = "";
    }
    renderStoreTypeIconPicker();
    syncStoreTypeModalSummary();
    setStoreTypeModalTab("basic");
  }

  // Supports the reset category editor branch of the super admin UI.
  function resetCategoryEditor({ clearInput = true } = {}) {
    state.editingCategoryName = "";
    if (elements.categoryInputLabel) {
      elements.categoryInputLabel.textContent = "Add Category";
    }
    if (elements.addCategoryButton) {
      elements.addCategoryButton.textContent = "Add";
    }
    if (elements.cancelCategoryEditButton) {
      elements.cancelCategoryEditButton.hidden = true;
    }
    if (clearInput && elements.categoryNameInput) {
      elements.categoryNameInput.value = "";
    }
    renderCategories(state.categories);
  }

  // Supports the reset store type editor branch of the super admin UI.
  function resetStoreTypeEditor({ clearInput = true } = {}) {
    const hadListEditState = Boolean(
      state.editingStoreTypeName ||
      state.inlineEditingCategoryStoreTypeName ||
      state.inlineEditingCategoryName ||
      state.inlineEditingStoreTypeSettingName ||
      state.inlineEditingStoreTypeSettingKey,
    );
    state.editingStoreTypeName = "";
    state.inlineEditingCategoryStoreTypeName = "";
    state.inlineEditingCategoryName = "";
    state.inlineEditingStoreTypeSettingName = "";
    state.inlineEditingStoreTypeSettingKey = "";
    resetInlineStoreTypeAssetDraft();
    if (elements.storeTypeInputLabel) {
      elements.storeTypeInputLabel.textContent = "Business Type Name";
    }
    if (elements.addStoreTypeButton) {
      elements.addStoreTypeButton.textContent = "Add Business Type";
    }
    if (elements.cancelStoreTypeEditButton) {
      elements.cancelStoreTypeEditButton.hidden = false;
    }
    if (clearInput && elements.storeTypeNameInput) {
      elements.storeTypeNameInput.value = "";
    }
    if (clearInput) {
      if (elements.storeTypeCategoryInput) {
        elements.storeTypeCategoryInput.value = "";
      }
      if (elements.storeTypeStatusSelect) {
        elements.storeTypeStatusSelect.value = "active";
      }
      if (elements.storeTypeCommissionRateInput) {
        elements.storeTypeCommissionRateInput.value = "";
      }
      if (elements.storeTypeServiceFeeInput) {
        elements.storeTypeServiceFeeInput.value = "";
      }
      syncStoreTypePlatformSelect("shop");
      if (elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      if (elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      }
      if (elements.storeTypeIconSearchInput) {
        elements.storeTypeIconSearchInput.value = "";
      }
      state.storeTypeDraftImageUrl = "";
      state.storeTypeDraftIconUrl = "";
      state.storeTypeDraftIconName = "";
      state.storeTypeIconSearchTerm = "";
      state.storeTypeIconVisibleCount = 0;
      state.storeTypeDraftImageFile = null;
      state.storeTypeDraftIconFile = null;
      state.storeTypeDraftCategories = [];
      state.storeTypeDraftCategoryDetails = [];
      renderStoreTypeDraftCategories();
      renderStoreTypeIconPicker();
      syncStoreTypeModalSummary();
      setStoreTypeModalTab("basic");
    }
    // Only rebuild the list when leaving an inline/list edit — not on every Add open.
    if (hadListEditState) {
      renderStoreTypes(state.storeTypes);
    }
  }

  // Checks whether store type modal visible is true for the current record or UI state.
  function isStoreTypeModalVisible() {
    return (
      elements.storeTypeModalOverlay instanceof HTMLElement &&
      !elements.storeTypeModalOverlay.hidden
    );
  }

  // Updates store type modal open and synchronizes related UI state.
  function setStoreTypeModalOpen(isOpen, { resetEditor = false, restoreFocus = true } = {}) {
    const overlay = elements.storeTypeModalOverlay;

    if (!(overlay instanceof HTMLElement)) {
      if (isOpen) {
        elements.storeTypeNameInput?.focus();
      }
      return;
    }

    if (storeTypeModalCloseTimer) {
      window.clearTimeout(storeTypeModalCloseTimer);
      storeTypeModalCloseTimer = 0;
    }

    if (storeTypeModalFocusTimer) {
      window.clearTimeout(storeTypeModalFocusTimer);
      storeTypeModalFocusTimer = 0;
    }

    if (isOpen) {
      storeTypeModalScrollSnapshot = getSuperAdminScrollSnapshot();
      if (resetEditor) {
        resetStoreTypeEditor();
      }

      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      elements.openStoreTypeModalButton?.setAttribute("aria-expanded", "true");

      window.requestAnimationFrame(() => {
        overlay.classList.add("is-open");
      });

      storeTypeModalFocusTimer = window.setTimeout(() => {
        storeTypeModalFocusTimer = 0;
        if (elements.storeTypeNameInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.storeTypeNameInput);
          elements.storeTypeNameInput.select();
          restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);
          return;
        }
        focusWithoutScroll(elements.storeTypeModalDialog);
        restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);
      }, 90);
      return;
    }

    setStoreTypePlatformDropdownOpen(false);
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    elements.openStoreTypeModalButton?.setAttribute("aria-expanded", "false");
    restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);

    storeTypeModalCloseTimer = window.setTimeout(() => {
      overlay.hidden = true;
      storeTypeModalCloseTimer = 0;
      if (restoreFocus) {
        focusWithoutScroll(elements.openStoreTypeModalButton);
      }
      restoreSuperAdminScrollSnapshotStable(storeTypeModalScrollSnapshot);
      storeTypeModalScrollSnapshot = null;
    }, 180);
  }

  // Closes store type modal and cleans up related state.
  function closeStoreTypeModal({ resetEditor = true, restoreFocus = true } = {}) {
    if (resetEditor) {
      resetStoreTypeEditor();
    }
    setStoreTypeModalOpen(false, { restoreFocus });
  }

  function isStoreTypeCategoryModalVisible() {
    return (
      elements.storeTypeCategoryModalOverlay instanceof HTMLElement &&
      !elements.storeTypeCategoryModalOverlay.hidden
    );
  }

  function setStoreTypeCategoryModalOpen(isOpen, {
    storeTypeName = "",
    categoryName = "",
    focusInput = true,
    restoreFocus = true,
  } = {}) {
    const overlay = elements.storeTypeCategoryModalOverlay;
    if (!(overlay instanceof HTMLElement)) {
      return;
    }

    if (storeTypeCategoryModalCloseTimer) {
      window.clearTimeout(storeTypeCategoryModalCloseTimer);
      storeTypeCategoryModalCloseTimer = 0;
    }
    if (storeTypeCategoryModalFocusTimer) {
      window.clearTimeout(storeTypeCategoryModalFocusTimer);
      storeTypeCategoryModalFocusTimer = 0;
    }

    if (isOpen) {
      const storeTypeRecord = getStoreTypeRecordByName(storeTypeName);
      if (!storeTypeRecord) {
        setFeedback("Business type not found.", "error");
        return;
      }

      activeStoreTypeCategoryTrigger = document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
      storeTypeCategoryModalScrollSnapshot = getSuperAdminScrollSnapshot();
      state.categoryModalStoreTypeName = storeTypeRecord.name;
      state.storeTypeDraftCategories = [...storeTypeRecord.categories];
      state.storeTypeDraftCategoryDetails = storeTypeRecord.categoryStats.map((detail) => ({ ...detail }));
      if (elements.storeTypeCategoryBusinessName) {
        elements.storeTypeCategoryBusinessName.textContent = storeTypeRecord.name;
      }
      resetStoreTypeCategoryComposer();
      renderStoreTypeDraftCategories();
      if (categoryName) editStoreTypeDraftCategory(categoryName);

      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      window.requestAnimationFrame(() => overlay.classList.add("is-open"));
      storeTypeCategoryModalFocusTimer = window.setTimeout(() => {
        storeTypeCategoryModalFocusTimer = 0;
        if (focusInput && elements.storeTypeCategoryInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.storeTypeCategoryInput);
          restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
          return;
        }
        focusWithoutScroll(elements.storeTypeCategoryModalDialog);
        restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
      }, 90);
      return;
    }

    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
    storeTypeCategoryModalCloseTimer = window.setTimeout(() => {
      overlay.hidden = true;
      storeTypeCategoryModalCloseTimer = 0;
      state.categoryModalStoreTypeName = "";
      state.storeTypeDraftCategories = [];
      state.storeTypeDraftCategoryDetails = [];
      resetStoreTypeCategoryComposer();
      if (restoreFocus) {
        focusWithoutScroll(activeStoreTypeCategoryTrigger);
      }
      restoreSuperAdminScrollSnapshotStable(storeTypeCategoryModalScrollSnapshot);
      storeTypeCategoryModalScrollSnapshot = null;
      activeStoreTypeCategoryTrigger = null;
    }, 180);
  }

  async function handleSaveStoreTypeCategories({
    closeModal = true,
    includePendingCategory = true,
    requirePendingCategory = false,
    showSuccess = true,
    successTitle = "Categories Updated",
  } = {}) {
    const storeTypeName = normalizeCategoryName(state.categoryModalStoreTypeName);
    if (!storeTypeName) {
      setFeedback("Select a business type first.", "error");
      return;
    }

    const pendingCategoryName = normalizeCategoryName(elements.storeTypeCategoryInput?.value);
    const hasPendingCategoryAssets =
      state.storeTypeCategoryDraftImageFile instanceof File
      || state.storeTypeCategoryDraftIconFile instanceof File
      || Boolean(state.storeTypeCategoryDraftImageUrl)
      || Boolean(state.storeTypeCategoryDraftIconUrl);
    if (includePendingCategory && !pendingCategoryName && hasPendingCategoryAssets) {
      setFeedback("Enter a category name before saving its image and icon.", "error");
      elements.storeTypeCategoryInput?.focus();
      return;
    }
    if (includePendingCategory && requirePendingCategory && !pendingCategoryName) {
      setFeedback("Enter a category name first.", "error");
      elements.storeTypeCategoryInput?.focus();
      return;
    }
    if (includePendingCategory && pendingCategoryName && !addStoreTypeDraftCategory({ focusInput: false })) {
      return;
    }

    if (!await requireSuperAdminFingerprint("add or save categories")) {
      return;
    }

    try {
      if (elements.addStoreTypeCategoryButton) {
        elements.addStoreTypeCategoryButton.disabled = true;
      }
      const categoryDetails = await uploadStoreTypeCategoryDetails();
      state.storeTypeDraftCategoryDetails = categoryDetails.map((detail) => ({ ...detail }));
      renderStoreTypeDraftCategories();
      setFeedback(`Updating categories for ${storeTypeName}...`);
      const response = await fetch("/api/super-admin/store-types", {
        method: "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify({
          oldName: storeTypeName,
          name: storeTypeName,
          categories: state.storeTypeDraftCategories,
          categoryDetails,
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to update categories.");
      }

      setStoreTypeData(
        Array.isArray(data.storeTypes) ? data.storeTypes : state.storeTypes,
        Array.isArray(data.storeTypeDetails) ? data.storeTypeDetails : null,
      );
      if (closeModal) {
        setStoreTypeCategoryModalOpen(false, { restoreFocus: false });
      }
      const successMessage = `Categories for ${storeTypeName} updated.`;
      if (showSuccess) {
        void showSuccessValidationModal(successTitle, successMessage);
      } else {
        setFeedback("");
      }
      return true;
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to update categories.", "error");
      elements.storeTypeCategoryInput?.focus();
      return false;
    } finally {
      if (elements.addStoreTypeCategoryButton) {
        elements.addStoreTypeCategoryButton.disabled = false;
      }
    }
  }

  //ito pwedi idelete
