  // end of reportcenter js

  function getReportDayBucket(createdAt) {
    const date = new Date(createdAt);
    if (!Number.isFinite(date.getTime())) {
      return { key: "older", label: "Older" };
    }
    const now = new Date();
    const ageMs = now.getTime() - date.getTime();
    // Fresh arrivals stay under Newest for 3 hours, then move to Today.
    const newestWindowMs = 3 * 60 * 60 * 1000;
    if (ageMs >= 0 && ageMs < newestWindowMs) {
      return { key: "newest", label: "Newest" };
    }
    const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startYesterday = new Date(startToday);
    startYesterday.setDate(startYesterday.getDate() - 1);
    const startDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    if (startDate.getTime() === startToday.getTime()) {
      return { key: "today", label: "Today" };
    }
    if (startDate.getTime() === startYesterday.getTime()) {
      return { key: "yesterday", label: "Yesterday" };
    }
    return { key: "older", label: "Older" };
  }

  function getReportDayBucketSortRank(key) {
    switch (String(key || "").trim().toLowerCase()) {
      case "newest":
        return 0;
      case "today":
        return 1;
      case "yesterday":
        return 2;
      case "older":
      default:
        return 3;
    }
  }

  function createReportDayHeading(label) {
    const heading = document.createElement("li");
    heading.className = "sa-report-board__day";
    heading.setAttribute("aria-hidden", "true");
    const text = document.createElement("span");
    text.textContent = label;
    heading.append(text);
    return heading;
  }

  function getReportDayStartMs(createdAt) {
    const date = new Date(createdAt);
    if (!Number.isFinite(date.getTime())) {
      return 0;
    }
    return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
  }

  function compareReportsUnreadNewestFirst(left, right, isUnreadFn) {
    const leftUnread = typeof isUnreadFn === "function" && isUnreadFn(left) ? 1 : 0;
    const rightUnread = typeof isUnreadFn === "function" && isUnreadFn(right) ? 1 : 0;
    if (leftUnread !== rightUnread) {
      return rightUnread - leftUnread;
    }
    const leftAt = Date.parse(String(left?.createdAt || "")) || 0;
    const rightAt = Date.parse(String(right?.createdAt || "")) || 0;
    return rightAt - leftAt;
  }

  function compareReportsDayThenUnreadNewest(left, right, isUnreadFn) {
    const leftBucket = getReportDayBucket(left?.createdAt);
    const rightBucket = getReportDayBucket(right?.createdAt);
    // Newest → Today → Yesterday → Older
    const leftRank = getReportDayBucketSortRank(leftBucket.key);
    const rightRank = getReportDayBucketSortRank(rightBucket.key);
    if (leftRank !== rightRank) {
      return leftRank - rightRank;
    }
    if (leftBucket.key === "older") {
      const leftDay = getReportDayStartMs(left?.createdAt);
      const rightDay = getReportDayStartMs(right?.createdAt);
      if (leftDay !== rightDay) {
        return rightDay - leftDay;
      }
    }
    return compareReportsUnreadNewestFirst(left, right, isUnreadFn);
  }

  function compareReportsByCreatedAtDesc(left, right) {
    const leftAt = Date.parse(String(left?.createdAt || "")) || 0;
    const rightAt = Date.parse(String(right?.createdAt || "")) || 0;
    return rightAt - leftAt;
  }

  function getStableReportDayBucket(report, bucketMap) {
    const key = getReportReadKey(report);
    if (key && bucketMap instanceof Map && bucketMap.has(key)) {
      return bucketMap.get(key);
    }
    const bucket = getReportDayBucket(report?.createdAt);
    if (key && bucketMap instanceof Map) {
      bucketMap.set(key, bucket);
    }
    return bucket;
  }

  function stabilizeReportListOrder(orderKeys, reports, isUnreadFn) {
    const list = Array.isArray(orderKeys) ? orderKeys : [];
    const incoming = Array.isArray(reports) ? reports : [];
    const byKey = new Map();
    for (const report of incoming) {
      const key = getReportReadKey(report);
      if (key) {
        byKey.set(key, report);
      }
    }

    if (!list.length) {
      const sorted = [...incoming].sort((left, right) =>
        compareReportsDayThenUnreadNewest(left, right, isUnreadFn),
      );
      list.splice(0, list.length, ...sorted.map((report) => getReportReadKey(report)).filter(Boolean));
      return sorted;
    }

    const known = new Set(list);
    const newUnread = incoming
      .filter((report) => {
        const key = getReportReadKey(report);
        return Boolean(key) && !known.has(key) && typeof isUnreadFn === "function" && isUnreadFn(report);
      })
      .sort(compareReportsByCreatedAtDesc);
    const kept = list.filter((key) => byKey.has(key));
    const placed = new Set([
      ...newUnread.map((report) => getReportReadKey(report)),
      ...kept,
    ]);
    const newRead = incoming
      .filter((report) => {
        const key = getReportReadKey(report);
        return Boolean(key) && !placed.has(key);
      })
      .sort(compareReportsByCreatedAtDesc);

    const next = [
      ...newUnread.map((report) => getReportReadKey(report)),
      ...kept,
    ];
    for (const report of newRead) {
      const key = getReportReadKey(report);
      const created = Date.parse(String(report?.createdAt || "")) || 0;
      let inserted = false;
      for (let index = 0; index < next.length; index += 1) {
        const other = byKey.get(next[index]);
        const otherCreated = Date.parse(String(other?.createdAt || "")) || 0;
        if (created > otherCreated) {
          next.splice(index, 0, key);
          inserted = true;
          break;
        }
      }
      if (!inserted) {
        next.push(key);
      }
    }

    list.splice(0, list.length, ...next);
    return next.map((key) => byKey.get(key)).filter(Boolean);
  }

  function appendReportRowsWithDayGroups(host, reports, createRow, options = {}) {
    if (!(host instanceof HTMLElement)) {
      return;
    }
    const isUnreadFn = typeof options.isUnread === "function" ? options.isUnread : null;
    const sorted = Array.isArray(options.orderKeys)
      ? stabilizeReportListOrder(options.orderKeys, reports, isUnreadFn)
      : [...(Array.isArray(reports) ? reports : [])].sort((left, right) =>
          compareReportsDayThenUnreadNewest(left, right, isUnreadFn),
        );
    const nodes = [];
    let lastKey = "";
    for (const report of sorted) {
      const bucket = getStableReportDayBucket(report, options.dayBuckets);
      if (bucket.key !== lastKey) {
        lastKey = bucket.key;
        nodes.push(createReportDayHeading(bucket.label));
      }
      nodes.push(createRow(report));
    }
    host.replaceChildren(...nodes);
  }

  function getReportCaseCode(report) {
    const publicId = String(report?.reportId || "").trim().toUpperCase();
    if (/^(RPT|LST)-\d{6}-[A-Z2-9]{4,}$/.test(publicId)) {
      return publicId;
    }
    const raw = String(report?.id || "")
      .replace(/^(cr|lr)[_-]*/i, "")
      .replace(/[^a-z0-9]/gi, "")
      .slice(-6)
      .toUpperCase();
    const isListing = String(report?.scope || "").toLowerCase() === "listing"
      || /^lr[_-]/i.test(String(report?.id || ""));
    return `${isListing ? "#LST" : "#CR"}${raw || "000000"}`;
  }

