  function openSuperAdminCompactDeleteModal({
    title,
    message,
    titlePrefix = "super-admin-delete-title",
  } = {}) {
    closeProductDeleteModal(false);
    const modalTitle = String(title || "Delete this item?").trim() || "Delete this item?";
    const modalMessage = String(message || "This action cannot be undone and will be permanent.").trim()
      || "This action cannot be undone and will be permanent.";
    const titleId = `${titlePrefix}-${Date.now()}`;

    return new Promise((resolve) => {
      activeProductDeleteModalResolve = resolve;
      const overlay = document.createElement("div");
      overlay.className = "super-admin-product-delete-modal-overlay";
      overlay.setAttribute("aria-hidden", "false");

      const dialog = document.createElement("section");
      dialog.className = "super-admin-product-delete-modal";
      dialog.setAttribute("role", "dialog");
      dialog.setAttribute("aria-modal", "true");
      dialog.setAttribute("aria-labelledby", titleId);
      dialog.tabIndex = -1;

      const closeButton = document.createElement("button");
      closeButton.type = "button";
      closeButton.className = "super-admin-product-delete-modal__close";
      closeButton.setAttribute("aria-label", "Close delete confirmation");
      closeButton.innerHTML = createCloseIconSvg();

      const icon = document.createElement("span");
      icon.className = "super-admin-product-delete-modal__icon";
      icon.setAttribute("aria-hidden", "true");
      icon.innerHTML = '<img src="/assets/super-admin-delete-3d.png?v=sa-delete-3d-1" alt="" decoding="async" />';

      const header = document.createElement("div");
      header.className = "super-admin-product-delete-modal__header";
      header.innerHTML = `
        <h2 id="${titleId}">${escapeHtml(modalTitle)}</h2>
        <p>${escapeHtml(modalMessage)}</p>
      `;

      const content = document.createElement("div");
      content.className = "super-admin-product-delete-modal__content";

      const actions = document.createElement("div");
      actions.className = "super-admin-product-delete-modal__actions";
      const cancelButton = document.createElement("button");
      cancelButton.type = "button";
      cancelButton.className = "super-admin-product-delete-modal__cancel";
      cancelButton.textContent = "Cancel";
      const confirmButton = document.createElement("button");
      confirmButton.type = "button";
      confirmButton.className = "super-admin-product-delete-modal__confirm";
      confirmButton.innerHTML = `
        ${createIconSvg(defaultTrashIconPaths)}
        <span>Delete</span>
      `;
      actions.append(cancelButton, confirmButton);

      dialog.append(closeButton, icon, header, content, actions);
      overlay.append(dialog);
      closeButton.addEventListener("click", () => closeProductDeleteModal(false));
      cancelButton.addEventListener("click", () => closeProductDeleteModal(false));
      confirmButton.addEventListener("click", () => closeProductDeleteModal(true));
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay) {
          closeProductDeleteModal(false);
        }
      });

      document.body.append(overlay);
      document.body.classList.add("super-admin-product-delete-open");
      activeProductDeleteModal = overlay;
      window.requestAnimationFrame(() => {
        overlay.classList.add("is-open");
        cancelButton.focus({ preventScroll: true });
      });
    });
  }

