  function createAiProviderAvatar(status, extraClassName = "") {
    const avatar = document.createElement("span");
    avatar.className = `super-admin-integrated-card__avatar buyer-data-list-avatar super-admin-ai-provider-table-avatar ${extraClassName}`.trim();
    if (status.provider) {
      avatar.classList.add(`is-${status.provider}`);
    }
    avatar.setAttribute("aria-hidden", "true");
    avatar.innerHTML = createAiProviderLogoMarkup(status.provider);
    return avatar;
  }

  function applyAiIntegrationCollection(data, { persist = false, selectedId = "" } = {}) {
    const integrations = Array.isArray(data?.integrations)
      ? data.integrations.map((item) => normalizeImageEnhancementIntegrationStatus(item))
      : data?.configured
        ? [normalizeImageEnhancementIntegrationStatus(data)]
        : [];
    state.imageEnhancementIntegrations = integrations;
    if (persist) {
      state.imageEnhancementPersistedIntegrations = integrations.map((item) => (
        normalizeImageEnhancementIntegrationStatus(item)
      ));
    }
    const preferredId = String(selectedId || state.imageEnhancementEditingId || "").trim();
    const selected = integrations.find((item) => item.id && item.id === preferredId)
      || integrations.find((item) => item.launched)
      || integrations[0]
      || normalizeImageEnhancementIntegrationStatus({});
    state.imageEnhancementIntegration = selected;
    state.imageEnhancementEditingId = selected.id || "";
    if (persist) {
      state.imageEnhancementPersistedIntegration = selected.configured
        ? normalizeImageEnhancementIntegrationStatus(selected)
        : null;
    }
    return selected;
  }

  function getPersistedImageEnhancementIntegrationStatus(idInput = "") {
    const preferredId = String(idInput || state.imageEnhancementEditingId || "").trim();
    const persistedList = Array.isArray(state.imageEnhancementPersistedIntegrations)
      ? state.imageEnhancementPersistedIntegrations
      : [];
    const match = persistedList.find((item) => item.id && item.id === preferredId);
    if (match) {
      return normalizeImageEnhancementIntegrationStatus(match);
    }
    if (state.imageEnhancementPersistedIntegration) {
      return normalizeImageEnhancementIntegrationStatus(
        state.imageEnhancementPersistedIntegration,
      );
    }
    const currentStatus = normalizeImageEnhancementIntegrationStatus(
      state.imageEnhancementIntegration,
    );
    return currentStatus.preview
      ? normalizeImageEnhancementIntegrationStatus({})
      : currentStatus;
  }

  function setImageEnhancementFeedbackElement(element, message = "", mode = "") {
    if (!(element instanceof HTMLElement)) {
      return;
    }
    const normalizedMessage = String(message || "").trim();
    element.textContent = normalizedMessage;
    element.hidden = !normalizedMessage;
    element.classList.toggle("is-success", mode === "success");
    element.classList.toggle("is-info", mode === "info");
  }

  function setImageEnhancementFeedback(message = "", mode = "") {
    setImageEnhancementFeedbackElement(
      elements.imageEnhancementFeedback,
      message,
      mode,
    );
  }

  function setImageEnhancementModalFeedback(message = "", mode = "") {
    setImageEnhancementFeedbackElement(
      elements.imageEnhancementModalFeedback,
      message,
      mode,
    );
  }

  function setImageEnhancementTableFeedback(message = "", mode = "") {
    setImageEnhancementFeedbackElement(
      elements.imageEnhancementTableFeedback,
      message,
      mode,
    );
  }

  function getAiIntegrationModelLabel(status, type) {
    const modelId = String(type === "image" ? status.imageModel : status.chatModel).trim();
    if (!modelId) {
      return "Not selected";
    }
    const models = Array.isArray(status.availableModels?.[type])
      ? status.availableModels[type]
      : [];
    return models.find((model) => model.id === modelId)?.label || modelId;
  }

  function createAiShowcaseStat(iconPaths, value, label) {
    const stat = document.createElement("div");
    stat.className = "business-type-showcase__stat";
    const icon = document.createElement("span");
    icon.className = "business-type-showcase__stat-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.innerHTML = createIconSvg(iconPaths);
    const copy = document.createElement("span");
    copy.className = "business-type-showcase__stat-copy";
    const strong = document.createElement("strong");
    strong.textContent = value;
    const caption = document.createElement("span");
    caption.textContent = label;
    copy.append(strong, caption);
    stat.append(icon, copy);
    return stat;
  }

  function createAiShowcaseSetting(label, value) {
    const setting = document.createElement("div");
    setting.className = "business-type-showcase__setting sa-ai-showcase__setting";
    const settingLabel = document.createElement("span");
    settingLabel.className = "business-type-showcase__setting-label";
    settingLabel.textContent = label;
    const settingValue = document.createElement("div");
    settingValue.className = "business-type-showcase__setting-value";
    if (value instanceof Node) {
      settingValue.append(value);
    } else {
      const strong = document.createElement("strong");
      strong.textContent = String(value || "—");
      settingValue.append(strong);
    }
    setting.append(settingLabel, settingValue);
    return setting;
  }

  function closeImageEnhancementDrawer({ restoreFocus = true } = {}) {
    const wasOpen = elements.imageEnhancementDrawer instanceof HTMLElement
      && !elements.imageEnhancementDrawer.hidden;
    closeIntegratedDrawers();
    if (!restoreFocus || !wasOpen || state.activeSection !== "ai-integration") {
      return;
    }
    window.requestAnimationFrame(() => {
      const returnTarget = elements.imageEnhancementList?.querySelector(
        ".sa-ai-showcase__identity",
      ) || elements.imageEnhancementSyncModelsButton;
      focusWithoutScroll(returnTarget);
    });
  }

  function setImageEnhancementDrawerOpen(isOpen, integrationId = "") {
    const drawer = elements.imageEnhancementDrawer;
    if (!(drawer instanceof HTMLElement)) {
      return;
    }
    if (isOpen) {
      if (integrationId) {
        state.imageEnhancementEditingId = String(integrationId).trim();
      }
      const status = getPersistedImageEnhancementIntegrationStatus(state.imageEnhancementEditingId);
      if (!status.configured) {
        setImageEnhancementTableFeedback(
          "Sync provider models before opening integration settings.",
        );
        return;
      }
      closeIntegratedDrawers();
      state.imageEnhancementIntegration = normalizeImageEnhancementIntegrationStatus(status);
      state.imageEnhancementEditingId = status.id || "";
      state.imageEnhancementSettingsDirty = false;
      setImageEnhancementFeedback("");
      openSuperAdminRightDrawer(drawer, elements.imageEnhancementDrawerBackdrop, {
        onOpened: () => {
          elements.imageEnhancementDrawerClose?.focus({ preventScroll: true });
        },
      });
      syncImageEnhancementIntegrationUi();
      return;
    }
    closeImageEnhancementDrawer();
  }

  function createImageEnhancementIntegrationRow(status) {
    const row = document.createElement("article");
    row.className = "super-admin-company-showcase business-type-showcase super-admin-ai-data-row sa-ai-showcase sa-showcase-card";
    row.dataset.aiIntegrationRow = status.id || status.provider || "ai-provider";
    row.dataset.aiProvider = status.provider || "ai";
    row.setAttribute("role", "listitem");
    row.setAttribute("aria-label", `${status.providerLabel || "AI provider"} integration`);

    const hero = document.createElement("div");
    hero.className = "business-type-showcase__hero";
    const content = document.createElement("div");
    content.className = "business-type-showcase__content";

    const identity = document.createElement("div");
    identity.className = "business-type-showcase__identity sa-ai-showcase__identity";
    identity.tabIndex = -1;
    const iconWrap = document.createElement("span");
    iconWrap.className = "business-type-showcase__icon-wrap";
    const avatar = createAiProviderAvatar(status, "business-type-showcase__icon sa-ai-showcase__provider-icon");
    iconWrap.append(avatar);
    const titleWrap = document.createElement("div");
    titleWrap.className = "business-type-showcase__heading";
    const titleRow = document.createElement("div");
    titleRow.className = "business-type-showcase__title-row";
    const title = document.createElement("h3");
    title.className = "business-type-showcase__title";
    title.textContent = status.providerLabel || "AI Provider";
    const statusBadge = document.createElement("span");
    statusBadge.className = `sa-ai-showcase__status ${status.launched ? "is-live" : "is-ready"}`;
    const statusBadgeDot = document.createElement("span");
    statusBadgeDot.setAttribute("aria-hidden", "true");
    const statusBadgeText = document.createElement("span");
    statusBadgeText.textContent = status.launched ? "Live" : "Ready";
    statusBadge.append(statusBadgeDot, statusBadgeText);

    const quickActions = document.createElement("div");
    quickActions.className = "super-admin-company-card__quick-actions partner-data-list-row__quick-actions sa-ai-showcase__actions";
    quickActions.setAttribute("aria-label", `Actions for ${status.providerLabel || "AI provider"}`);
    const viewButton = document.createElement("button");
    viewButton.type = "button";
    viewButton.className = "super-admin-company-card__quick-action partner-data-action-button";
    viewButton.dataset.aiIntegrationAction = "view";
    viewButton.setAttribute("aria-label", `View ${status.providerLabel || "AI provider"} integration`);
    viewButton.title = "View integration";
    viewButton.innerHTML = createIconSvg(
      '<path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0"></path><circle cx="12" cy="12" r="3"></circle>',
    );
    const deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "super-admin-company-card__quick-action super-admin-company-card__quick-action--danger partner-data-action-button";
    deleteButton.dataset.aiIntegrationAction = "delete";
    deleteButton.setAttribute("aria-label", `Delete ${status.providerLabel || "AI provider"}`);
    deleteButton.title = "Delete integration";
    deleteButton.innerHTML = createIconSvg(integratedIconPaths.trash);
    quickActions.append(viewButton, deleteButton);

    titleRow.append(title, statusBadge, quickActions);
    const subtitle = document.createElement("p");
    subtitle.className = "business-type-showcase__tagline sa-ai-showcase__tagline";
    subtitle.textContent = status.modelsSyncedAt
      ? "Models synced from provider"
      : "Server-managed provider";
    titleWrap.append(titleRow, subtitle);
    identity.append(iconWrap, titleWrap);

    const description = document.createElement("p");
    description.className = "business-type-showcase__description sa-ai-showcase__description";
    description.textContent = status.launched
      ? "Serving system-wide AI features with the selected models and capability assignments."
      : "Connected system-wide and ready to launch after reviewing its models and capabilities.";

    const capabilityEntries = [
      ["chatbot", "Chatbot", '<path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4Z"></path>'],
      ["autoReply", "Auto-reply", '<path d="m9 17-5-5 5-5"></path><path d="M4 12h11a5 5 0 0 1 5 5v2"></path>'],
      ["imageEnhancement", "Photo enhance", '<rect width="18" height="18" x="3" y="3" rx="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-5-5L5 21"></path>'],
    ];
    const supportedCount = capabilityEntries.filter(([key]) => status.capabilities[key]?.supported).length;
    const enabledCount = capabilityEntries.filter(([key]) => status.capabilities[key]?.enabled).length;
    const stats = document.createElement("div");
    stats.className = "business-type-showcase__stats sa-ai-showcase__stats";
    stats.append(
      createAiShowcaseStat(
        '<path d="M12 2a4 4 0 0 0-4 4v1H6a3 3 0 0 0-3 3v2a3 3 0 0 0 3 3h1v3a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-3h1a3 3 0 0 0 3-3v-2a3 3 0 0 0-3-3h-2V6a4 4 0 0 0-4-4Z"></path><path d="M9 11h.01M15 11h.01"></path>',
        getAiIntegrationModelLabel(status, "chat"),
        "Chat model",
      ),
      createAiShowcaseStat(
        '<rect width="18" height="18" x="3" y="3" rx="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-5-5L5 21"></path>',
        getAiIntegrationModelLabel(status, "image"),
        "Image model",
      ),
      createAiShowcaseStat(
        integratedIconPaths.ai,
        `${enabledCount} of ${supportedCount}`,
        "Features enabled",
      ),
    );

    const settings = document.createElement("div");
    settings.className = "business-type-showcase__settings sa-ai-showcase__settings";
    settings.append(
      createAiShowcaseSetting("Scope", "System-wide"),
      createAiShowcaseSetting(
        "Model catalog",
        `${status.availableModels.chat.length + status.availableModels.image.length} models`,
      ),
      createAiShowcaseSetting(
        "Models synced",
        formatDateDay(status.modelsSyncedAt || status.verifiedAt || status.updatedAt),
      ),
    );
    content.append(identity, description, stats, settings);

    const media = document.createElement("div");
    media.className = "business-type-showcase__media sa-ai-showcase__media";
    media.setAttribute("aria-label", `${status.providerLabel || "AI provider"} integration overview`);
    const glow = document.createElement("div");
    glow.className = "sa-ai-showcase__glow";
    glow.setAttribute("aria-hidden", "true");
    const preview = document.createElement("div");
    preview.className = "sa-ai-showcase__preview";
    const previewHead = document.createElement("div");
    previewHead.className = "sa-ai-showcase__preview-head";
    const previewLogo = createAiProviderAvatar(status, "sa-ai-showcase__preview-logo");
    const previewIdentity = document.createElement("div");
    const eyebrow = document.createElement("span");
    eyebrow.className = "sa-ai-showcase__eyebrow";
    eyebrow.textContent = "AI provider";
    const previewTitle = document.createElement("h4");
    previewTitle.textContent = status.providerLabel || "AI Provider";
    previewIdentity.append(eyebrow, previewTitle);
    const liveIndicator = document.createElement("span");
    liveIndicator.className = `sa-ai-showcase__live-indicator ${status.launched ? "is-live" : "is-ready"}`;
    liveIndicator.textContent = status.launched ? "Live" : "Ready";
    previewHead.append(previewLogo, previewIdentity, liveIndicator);

    const modelGrid = document.createElement("div");
    modelGrid.className = "sa-ai-showcase__model-grid";
    for (const [label, value] of [
      ["Chat", getAiIntegrationModelLabel(status, "chat")],
      ["Image", getAiIntegrationModelLabel(status, "image")],
    ]) {
      const model = document.createElement("div");
      const modelLabel = document.createElement("span");
      modelLabel.textContent = label;
      const modelValue = document.createElement("strong");
      modelValue.textContent = value;
      model.append(modelLabel, modelValue);
      modelGrid.append(model);
    }

    const capabilityList = document.createElement("div");
    capabilityList.className = "sa-ai-showcase__capabilities";
    for (const [key, label, iconPaths] of capabilityEntries) {
      const capability = status.capabilities[key];
      const chip = document.createElement("span");
      chip.className = `sa-ai-showcase__capability ${capability?.enabled ? "is-enabled" : "is-disabled"}`;
      const chipIcon = document.createElement("span");
      chipIcon.setAttribute("aria-hidden", "true");
      chipIcon.innerHTML = createIconSvg(iconPaths);
      const chipLabel = document.createElement("span");
      chipLabel.textContent = label;
      chip.append(chipIcon, chipLabel);
      capabilityList.append(chip);
    }
    preview.append(previewHead, modelGrid, capabilityList);
    media.append(glow, preview);
    hero.append(content, media);
    row.append(hero);
    row.addEventListener("click", (event) => {
      const action = event.target instanceof Element
        ? event.target.closest("[data-ai-integration-action]")?.dataset.aiIntegrationAction
        : "";
      if (action === "delete") {
        event.preventDefault();
        void deleteImageEnhancementIntegration(status);
        return;
      }
      if (action === "view") {
        event.preventDefault();
        setImageEnhancementDrawerOpen(true, status.id);
      }
    });
    return row;
  }

  function renderImageEnhancementIntegrationTable() {
    const list = elements.imageEnhancementList;
    if (!(list instanceof HTMLElement)) {
      return;
    }
    const integrations = (
      Array.isArray(state.imageEnhancementPersistedIntegrations)
        ? state.imageEnhancementPersistedIntegrations
        : []
    ).filter((item) => item.configured);
    const total = integrations.length;
    const live = integrations.filter((item) => item.launched).length;
    const ready = integrations.filter((item) => item.configured && !item.launched).length;
    if (elements.imageEnhancementTotal) elements.imageEnhancementTotal.textContent = `(${numberText(total)})`;
    if (elements.imageEnhancementStatTotal) elements.imageEnhancementStatTotal.textContent = numberText(total);
    if (elements.imageEnhancementStatLive) elements.imageEnhancementStatLive.textContent = numberText(live);
    if (elements.imageEnhancementStatReady) elements.imageEnhancementStatReady.textContent = numberText(ready);
    setSuperAdminRawTrendPair(elements.imageEnhancementStatLivePercent, live, 0);
    setSuperAdminRawTrendPair(elements.imageEnhancementStatReadyPercent, ready, 0);
    if (elements.imageEnhancementPageMeta) {
      elements.imageEnhancementPageMeta.textContent = total
        ? `Showing 1 to ${total} of ${total} AI integrations`
        : "Showing 0 to 0 of 0 AI integrations";
    }

    list.replaceChildren();
    if (!total) {
      const empty = document.createElement("div");
      empty.className = "buyer-data-empty partner-data-list-empty super-admin-ai-data-list__empty";
      empty.textContent = state.imageEnhancementLoading
        ? "Loading AI integrations..."
        : "No server-configured AI provider found. Add provider credentials on the server, then select Sync Models.";
      list.append(empty);
      return;
    }
    const drawerOpen = elements.imageEnhancementDrawer instanceof HTMLElement
      && !elements.imageEnhancementDrawer.hidden;
    for (const status of integrations) {
      const row = createImageEnhancementIntegrationRow(status);
      row.classList.toggle(
        "is-selected",
        drawerOpen && Boolean(status.id) && status.id === state.imageEnhancementEditingId,
      );
      list.append(row);
    }
  }

  function setImageEnhancementBusyState() {
    const isBlockingBusy = Boolean(
      state.imageEnhancementLoading
      || state.imageEnhancementSaving
      || state.imageEnhancementLaunching
      || state.imageEnhancementSyncingModels,
    );
    const isBusy = Boolean(isBlockingBusy || state.imageEnhancementDetecting);
    const status = normalizeImageEnhancementIntegrationStatus(
      state.imageEnhancementIntegration,
    );
    if (elements.imageEnhancementApiKeyInput instanceof HTMLInputElement) {
      elements.imageEnhancementApiKeyInput.disabled = isBlockingBusy;
    }
    if (elements.imageEnhancementChatModelSelect instanceof HTMLSelectElement) {
      elements.imageEnhancementChatModelSelect.disabled = isBusy
        || !(status.capabilities.chatbot.supported || status.capabilities.autoReply.supported)
        || status.availableModels.chat.length === 0;
    }
    if (elements.imageEnhancementImageModelSelect instanceof HTMLSelectElement) {
      elements.imageEnhancementImageModelSelect.disabled = isBusy
        || !status.capabilities.imageEnhancement.supported
        || status.availableModels.image.length === 0;
    }
    syncAiModelDropdown(elements.imageEnhancementChatModelSelect);
    syncAiModelDropdown(elements.imageEnhancementImageModelSelect);
    for (const toggle of elements.imageEnhancementCapabilityToggles) {
      if (!(toggle instanceof HTMLInputElement)) {
        continue;
      }
      const capabilityKey = toggle.dataset.aiCapabilityToggle;
      const capability = status.capabilities[capabilityKey];
      const claimedBy = status.claimedByOthers?.[capabilityKey];
      toggle.disabled = isBusy || !capability?.supported || Boolean(claimedBy);
    }
    if (elements.imageEnhancementSaveButton instanceof HTMLButtonElement) {
      elements.imageEnhancementSaveButton.disabled = isBusy || !status.configured;
      elements.imageEnhancementSaveButton.classList.toggle(
        "is-loading",
        state.imageEnhancementSaving,
      );
      elements.imageEnhancementSaveButton.setAttribute(
        "aria-busy",
        state.imageEnhancementSaving ? "true" : "false",
      );
    }
    if (elements.imageEnhancementSecretToggle instanceof HTMLButtonElement) {
      elements.imageEnhancementSecretToggle.disabled = isBlockingBusy;
    }
    if (elements.imageEnhancementSyncModelsButton instanceof HTMLButtonElement) {
      elements.imageEnhancementSyncModelsButton.disabled = isBlockingBusy;
      elements.imageEnhancementSyncModelsButton.classList.toggle(
        "is-syncing",
        state.imageEnhancementSyncingModels,
      );
      elements.imageEnhancementSyncModelsButton.setAttribute(
        "aria-busy",
        state.imageEnhancementSyncingModels ? "true" : "false",
      );
      const label = elements.imageEnhancementSyncModelsButton.querySelector("span");
      if (label) {
        label.textContent = state.imageEnhancementSyncingModels
          ? "Syncing Models..."
          : "Sync Models";
      }
    }
    if (elements.imageEnhancementConnectButton instanceof HTMLButtonElement) {
      elements.imageEnhancementConnectButton.disabled = isBusy;
      elements.imageEnhancementConnectButton.classList.toggle(
        "is-loading",
        state.imageEnhancementSaving,
      );
      elements.imageEnhancementConnectButton.setAttribute(
        "aria-busy",
        (state.imageEnhancementSaving || state.imageEnhancementDetecting) ? "true" : "false",
      );
    }
    for (const modalButton of [
      elements.imageEnhancementApiKeyModalCloseButton,
      elements.imageEnhancementApiKeyModalCancelButton,
    ]) {
      if (modalButton instanceof HTMLButtonElement) {
        modalButton.disabled = state.imageEnhancementSaving;
      }
    }
    if (elements.imageEnhancementLaunchButton instanceof HTMLButtonElement) {
      elements.imageEnhancementLaunchButton.disabled = isBusy
        || !status.configured
        || state.imageEnhancementSettingsDirty;
      elements.imageEnhancementLaunchButton.classList.toggle(
        "is-loading",
        state.imageEnhancementLaunching,
      );
      elements.imageEnhancementLaunchButton.setAttribute(
        "aria-busy",
        state.imageEnhancementLaunching ? "true" : "false",
      );
    }
  }

  function populateAiModelSelect(select, models, selectedModel, emptyLabel) {
    if (!(select instanceof HTMLSelectElement)) {
      return;
    }
    const normalizedModels = normalizeAiModelOptions(models);
    const selected = String(selectedModel || "").trim();
    const options = selected && !normalizedModels.some((model) => model.id === selected)
      ? [{ id: selected, label: selected }, ...normalizedModels]
      : normalizedModels;
    select.replaceChildren();
    if (options.length === 0) {
      const option = document.createElement("option");
      option.value = "";
      option.textContent = emptyLabel;
      select.appendChild(option);
      syncAiModelDropdown(select);
      return;
    }
    for (const model of options) {
      const option = document.createElement("option");
      option.value = model.id;
      option.textContent = model.label;
      select.appendChild(option);
    }
    select.value = options.some((model) => model.id === selected) ? selected : options[0].id;
    syncAiModelDropdown(select);
  }

  function getAiModelDropdownParts(select) {
    if (!(select instanceof HTMLSelectElement)) {
      return null;
    }
    const dropdown = select.closest("[data-ai-model-dropdown]");
    const trigger = dropdown?.querySelector("[data-ai-model-trigger]");
    const label = trigger?.querySelector("[data-ai-model-label]");
    const menu = dropdown?.querySelector("[data-ai-model-menu]");
    if (
      !(dropdown instanceof HTMLElement)
      || !(trigger instanceof HTMLButtonElement)
      || !(label instanceof HTMLElement)
      || !(menu instanceof HTMLElement)
    ) {
      return null;
    }
    return { dropdown, trigger, label, menu };
  }

  function closeAiModelDropdown(dropdown, { focusTrigger = false } = {}) {
    if (!(dropdown instanceof HTMLElement)) {
      return;
    }
    const trigger = dropdown.querySelector("[data-ai-model-trigger]");
    const menu = dropdown.querySelector("[data-ai-model-menu]");
    dropdown.classList.remove("is-open");
    if (trigger instanceof HTMLButtonElement) {
      trigger.setAttribute("aria-expanded", "false");
      if (focusTrigger) {
        trigger.focus();
      }
    }
    if (menu instanceof HTMLElement) {
      menu.hidden = true;
    }
  }

  function closeAiModelDropdowns(exceptDropdown = null) {
    document.querySelectorAll("[data-ai-model-dropdown].is-open").forEach((dropdown) => {
      if (dropdown !== exceptDropdown) {
        closeAiModelDropdown(dropdown);
      }
    });
  }

  function setAiModelDropdownOpen(dropdown, open, { focusSelected = false } = {}) {
    if (!(dropdown instanceof HTMLElement)) {
      return;
    }
    const trigger = dropdown.querySelector("[data-ai-model-trigger]");
    const menu = dropdown.querySelector("[data-ai-model-menu]");
    if (!(trigger instanceof HTMLButtonElement) || !(menu instanceof HTMLElement) || trigger.disabled) {
      closeAiModelDropdown(dropdown);
      return;
    }
    const shouldOpen = Boolean(open);
    closeAiModelDropdowns(shouldOpen ? dropdown : null);
    dropdown.classList.toggle("is-open", shouldOpen);
    trigger.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
    menu.hidden = !shouldOpen;
    if (shouldOpen && focusSelected) {
      window.requestAnimationFrame(() => {
        const selected = menu.querySelector(".super-admin-ai-model-select__option.is-selected:not(:disabled)");
        const first = menu.querySelector(".super-admin-ai-model-select__option:not(:disabled)");
        (selected || first)?.focus();
      });
    }
  }

  function syncAiModelDropdown(select) {
    const parts = getAiModelDropdownParts(select);
    if (!parts) {
      return;
    }
    const { dropdown, trigger, label, menu } = parts;
    const selectedOption = select.options[select.selectedIndex] || select.options[0] || null;
    label.textContent = selectedOption?.textContent?.trim() || "Select model";
    trigger.disabled = select.disabled;
    trigger.setAttribute("aria-disabled", select.disabled ? "true" : "false");

    const fragment = document.createDocumentFragment();
    Array.from(select.options).forEach((option) => {
      const value = String(option.value || "").trim();
      if (!value) {
        return;
      }
      const button = document.createElement("button");
      button.type = "button";
      button.className = "super-admin-company-card__action-item super-admin-ban-modal__reason-option super-admin-ai-model-select__option";
      button.dataset.aiModelOption = value;
      button.setAttribute("role", "option");
      button.setAttribute("aria-selected", option.selected ? "true" : "false");
      button.disabled = option.disabled;
      button.textContent = option.textContent?.trim() || value;
      button.classList.toggle("is-selected", option.selected);
      fragment.append(button);
    });
    menu.replaceChildren(fragment);
    if (select.disabled || menu.childElementCount === 0) {
      closeAiModelDropdown(dropdown);
    }
  }

  function focusAiModelDropdown(select) {
    const parts = getAiModelDropdownParts(select);
    if (parts?.trigger instanceof HTMLButtonElement) {
      parts.trigger.focus();
      return;
    }
    select?.focus?.();
  }

  function bindAiModelDropdown(select) {
    const parts = getAiModelDropdownParts(select);
    if (!parts || parts.dropdown.dataset.aiModelDropdownBound === "true") {
      return;
    }
    const { dropdown, trigger, menu } = parts;
    dropdown.dataset.aiModelDropdownBound = "true";
    trigger.addEventListener("click", () => {
      setAiModelDropdownOpen(dropdown, !dropdown.classList.contains("is-open"));
    });
    trigger.addEventListener("keydown", (event) => {
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        setAiModelDropdownOpen(dropdown, true, { focusSelected: true });
      }
    });
    menu.addEventListener("click", (event) => {
      const option = event.target instanceof Element
        ? event.target.closest("[data-ai-model-option]")
        : null;
      if (!(option instanceof HTMLButtonElement) || option.disabled) {
        return;
      }
      select.value = String(option.dataset.aiModelOption || "");
      closeAiModelDropdown(dropdown, { focusTrigger: true });
      select.dispatchEvent(new Event("change", { bubbles: true }));
    });
    menu.addEventListener("keydown", (event) => {
      const options = Array.from(
        menu.querySelectorAll(".super-admin-ai-model-select__option:not(:disabled)"),
      );
      const currentIndex = options.indexOf(document.activeElement);
      if (event.key === "Escape") {
        event.preventDefault();
        closeAiModelDropdown(dropdown, { focusTrigger: true });
        return;
      }
      if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key) || options.length === 0) {
        return;
      }
      event.preventDefault();
      const nextIndex = event.key === "Home"
        ? 0
        : event.key === "End"
          ? options.length - 1
          : event.key === "ArrowDown"
            ? (currentIndex + 1 + options.length) % options.length
            : (currentIndex - 1 + options.length) % options.length;
      options[nextIndex]?.focus();
    });
  }

  function getEnabledAiFeatureLabels(status) {
    const labels = {
      chatbot: "chatbot",
      autoReply: "automatic replies",
      imageEnhancement: "photo enhancement",
    };
    return Object.entries(status.capabilities)
      .filter(([, capability]) => capability.supported && capability.enabled)
      .map(([key]) => labels[key]);
  }

  function syncImageEnhancementIntegrationUi() {
    const status = normalizeImageEnhancementIntegrationStatus(
      state.imageEnhancementIntegration,
    );
    const persistedStatus = getPersistedImageEnhancementIntegrationStatus();
    state.imageEnhancementIntegration = status;

    populateAiModelSelect(
      elements.imageEnhancementChatModelSelect,
      status.availableModels.chat,
      status.chatModel,
      status.provider ? "No chat models available" : "Connect a provider first",
    );
    populateAiModelSelect(
      elements.imageEnhancementImageModelSelect,
      status.availableModels.image,
      status.imageModel,
      status.provider && !status.capabilities.imageEnhancement.supported
        ? `Not supported by ${status.providerLabel}`
        : "No image models available",
    );
    if (elements.imageEnhancementApiKeyInput instanceof HTMLInputElement) {
      elements.imageEnhancementApiKeyInput.placeholder = persistedStatus.configured
        ? "Paste a replacement API key"
        : "Paste your provider API key";
    }
    if (elements.imageEnhancementKeyHint) {
      elements.imageEnhancementKeyHint.textContent = state.imageEnhancementApiKeyMode === "replace"
        && persistedStatus.configured
        ? `Current key: ${persistedStatus.apiKeyMasked || "*******"}. Connecting a new key replaces this row only.`
        : "Each API key is added as its own AI integration. The key stays on the server and is never shown in full.";
    }
    if (elements.imageEnhancementDetectedProvider instanceof HTMLElement) {
      const label = elements.imageEnhancementDetectedProvider.querySelector("strong");
      const providerLogo = elements.imageEnhancementDetectedProvider.querySelector("i");
      elements.imageEnhancementDetectedProvider.classList.toggle("is-detected", Boolean(status.provider));
      if (label) {
        label.textContent = status.providerLabel || "Waiting for API key";
      }
      if (providerLogo instanceof HTMLElement) {
        providerLogo.classList.remove(
          "super-admin-ai-detected-provider__logo",
          "is-openai",
          "is-anthropic",
          "is-gemini",
        );
        providerLogo.innerHTML = "";
        if (status.provider) {
          providerLogo.classList.add("super-admin-ai-detected-provider__logo", `is-${status.provider}`);
          providerLogo.innerHTML = createAiProviderLogoMarkup(status.provider);
        }
      }
    }
    if (elements.imageEnhancementDetectedCopy) {
      const modelCount = status.availableModels.chat.length + status.availableModels.image.length;
      elements.imageEnhancementDetectedCopy.textContent = status.provider
        ? `${modelCount} compatible model${modelCount === 1 ? "" : "s"} found${status.verifiedAt ? " and verified" : ""}.`
        : "Paste a key, then detection runs automatically.";
    }
    if (elements.imageEnhancementImageModelHint) {
      elements.imageEnhancementImageModelHint.textContent = (
        status.provider && !status.capabilities.imageEnhancement.supported
      )
        ? `${status.providerLabel} supports chat here, but no compatible image model is available for Enhance Photo.`
        : status.provider === "gemini"
          ? "Uses a compatible Gemini image model for Enhance Photo in seller listings."
          : "Used by Enhance Photo in seller listings.";
    }
    if (elements.imageEnhancementDrawerProvider) {
      elements.imageEnhancementDrawerProvider.textContent = status.providerLabel || "No provider connected";
    }
    const drawerAvatar = elements.imageEnhancementDrawer?.querySelector(".super-admin-ai-provider-avatar");
    if (drawerAvatar instanceof HTMLElement) {
      drawerAvatar.classList.remove("is-openai", "is-anthropic", "is-gemini");
      if (status.provider) {
        drawerAvatar.classList.add(`is-${status.provider}`);
      }
      drawerAvatar.innerHTML = createAiProviderLogoMarkup(status.provider);
    }

    for (const toggle of elements.imageEnhancementCapabilityToggles) {
      if (!(toggle instanceof HTMLInputElement)) {
        continue;
      }
      const key = toggle.dataset.aiCapabilityToggle;
      const capability = status.capabilities[key];
      const claimedBy = status.claimedByOthers?.[key];
      toggle.checked = Boolean(capability?.supported && capability.enabled && !claimedBy);
      const row = elements.imageEnhancementCapabilityRows.find(
        (candidate) => candidate.dataset.aiCapabilityRow === key,
      );
      row?.classList.toggle("is-unsupported", !capability?.supported || Boolean(claimedBy));
      row?.classList.toggle("is-available", Boolean(capability?.available));
      row?.classList.toggle(
        "is-ready",
        Boolean(capability?.supported && capability.enabled && !capability.available && !claimedBy),
      );
      const statusLabel = row?.querySelector(`[data-ai-capability-status="${key}"]`);
      if (statusLabel) {
        const isLiveFeature = Boolean(capability?.available && !claimedBy);
        statusLabel.hidden = isLiveFeature;
        statusLabel.textContent = isLiveFeature
          ? ""
          : claimedBy
            ? `Used by ${claimedBy.providerLabel || "another AI"}`
            : !capability?.supported
              ? "Not supported"
              : capability.enabled
                ? "Enabled"
                : "Disabled";
      }
    }

    if (elements.imageEnhancementStatusBadge instanceof HTMLElement) {
      elements.imageEnhancementStatusBadge.classList.toggle(
        "is-configured",
        status.configured && !status.launched,
      );
      elements.imageEnhancementStatusBadge.classList.toggle(
        "is-launched",
        status.launched,
      );
      elements.imageEnhancementStatusBadge.classList.toggle(
        "is-not-launched",
        !status.launched,
      );
    }
    if (elements.imageEnhancementStatusLabel) {
      elements.imageEnhancementStatusLabel.textContent = status.launched
        ? "Launched"
        : status.configured
          ? "Ready to launch"
          : "Not configured";
    }
    if (elements.imageEnhancementLaunchCard instanceof HTMLElement) {
      elements.imageEnhancementLaunchCard.classList.toggle("is-launched", status.launched);
      elements.imageEnhancementLaunchCard.classList.toggle("is-not-launched", !status.launched);
    }
    if (elements.imageEnhancementLaunchTitle) {
      elements.imageEnhancementLaunchTitle.textContent = status.launched
        ? "AI integration is live"
        : status.configured
          ? "Integration ready to launch"
          : "Integration not launched";
    }
    if (elements.imageEnhancementLaunchCopy) {
      const enabledFeatures = getEnabledAiFeatureLabels(status);
      elements.imageEnhancementLaunchCopy.textContent = state.imageEnhancementSettingsDirty
        ? "Save the model and feature changes before changing the launch status."
        : status.launched
          ? `${status.providerLabel} is live for ${enabledFeatures.join(", ") || "the enabled AI services"}.`
          : status.configured
            ? "Launch this provider. Up to two integrations can stay live; each feature belongs to only one AI."
            : "Sync provider models first, then launch the service.";
    }
    if (elements.imageEnhancementLaunchLabel) {
      elements.imageEnhancementLaunchLabel.textContent = status.launched
        ? "Stop Integration"
        : "Launch Integration";
    }
    if (elements.imageEnhancementLaunchButton instanceof HTMLButtonElement) {
      elements.imageEnhancementLaunchButton.classList.toggle("is-stop", status.launched);
      elements.imageEnhancementLaunchButton.setAttribute(
        "aria-label",
        state.imageEnhancementSettingsDirty
          ? "Save settings before changing AI integration status"
          : status.launched
            ? "Stop AI integration"
            : "Launch AI integration",
      );
      elements.imageEnhancementLaunchButton.title = state.imageEnhancementSettingsDirty
        ? "Save settings first"
        : status.launched
          ? "Stop AI integration"
          : "Launch AI integration";
    }
    setImageEnhancementBusyState();
    renderImageEnhancementIntegrationTable();
  }

  async function loadImageEnhancementIntegrationStatus() {
    if (state.imageEnhancementLoading) {
      return;
    }
    state.imageEnhancementLoading = true;
    setImageEnhancementBusyState();
    renderImageEnhancementIntegrationTable();
    try {
      const response = await fetch("/api/super-admin/ai-integration", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to load the AI integration.");
      }
      applyAiIntegrationCollection(data, { persist: true });
      state.imageEnhancementSettingsDirty = false;
      state.imageEnhancementStatusLoaded = true;
      setImageEnhancementFeedback("");
      setImageEnhancementTableFeedback("");
    } catch (error) {
      state.imageEnhancementStatusLoaded = false;
      setImageEnhancementTableFeedback(
        error instanceof Error ? error.message : "Unable to load the AI integration.",
      );
    } finally {
      state.imageEnhancementLoading = false;
      syncImageEnhancementIntegrationUi();
    }
  }

  async function syncAiProviderModels() {
    if (
      state.imageEnhancementSyncingModels
      || state.imageEnhancementLoading
      || state.imageEnhancementSaving
      || state.imageEnhancementLaunching
    ) {
      return;
    }
    state.imageEnhancementSyncingModels = true;
    setImageEnhancementTableFeedback(
      "Syncing current models from the configured AI providers...",
      "info",
    );
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration/sync-models", {
        method: "POST",
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to sync AI provider models.");
      }
      applyAiIntegrationCollection(data, {
        persist: true,
        selectedId: state.imageEnhancementEditingId,
      });
      state.imageEnhancementSettingsDirty = false;
      state.imageEnhancementStatusLoaded = true;
      setImageEnhancementTableFeedback(
        data.message || "AI provider models are up to date.",
        "success",
      );
    } catch (error) {
      setImageEnhancementTableFeedback(
        error instanceof Error ? error.message : "Unable to sync AI provider models.",
      );
    } finally {
      state.imageEnhancementSyncingModels = false;
      syncImageEnhancementIntegrationUi();
    }
  }

  async function detectImageEnhancementProvider({ force = false } = {}) {
    if (state.imageEnhancementLoading || state.imageEnhancementSaving || state.imageEnhancementLaunching) {
      return;
    }
    const apiKey = String(elements.imageEnhancementApiKeyInput?.value || "").trim();
    if (!apiKey) {
      state.imageEnhancementIntegration = isImageEnhancementApiKeyModalVisible()
        ? normalizeImageEnhancementIntegrationStatus({})
        : getPersistedImageEnhancementIntegrationStatus();
      state.imageEnhancementLastDetectionSignature = "";
      syncImageEnhancementIntegrationUi();
      if (force) {
        setImageEnhancementModalFeedback("Enter an API key to detect its provider.");
        elements.imageEnhancementApiKeyInput?.focus();
      }
      return;
    }
    const signature = apiKey;
    if (!force && signature === state.imageEnhancementLastDetectionSignature) {
      return;
    }

    const requestSequence = state.imageEnhancementDetectionSequence + 1;
    state.imageEnhancementDetectionSequence = requestSequence;
    state.imageEnhancementLastDetectionSignature = signature;
    state.imageEnhancementDetecting = true;
    setImageEnhancementModalFeedback(
      "Detecting the provider and loading compatible models...",
      "info",
    );
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration/detect", {
        method: "POST",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(
          state.imageEnhancementApiKeyMode === "replace" && state.imageEnhancementEditingId
            ? { id: state.imageEnhancementEditingId, apiKey }
            : { apiKey },
        ),
      });
      const data = await response.json().catch(() => ({}));
      if (requestSequence !== state.imageEnhancementDetectionSequence) {
        return;
      }
      if (!response.ok) {
        throw new Error(data.message || "Unable to detect the AI provider.");
      }
      state.imageEnhancementIntegration = normalizeImageEnhancementIntegrationStatus(data);
      state.imageEnhancementStatusLoaded = true;
      syncImageEnhancementIntegrationUi();
      const detected = state.imageEnhancementIntegration;
      const modelCount = detected.availableModels.chat.length + detected.availableModels.image.length;
      setImageEnhancementModalFeedback(
        `${detected.providerLabel || "AI provider"} detected. ${modelCount} compatible model${modelCount === 1 ? "" : "s"} available.`,
        "success",
      );
    } catch (error) {
      if (requestSequence === state.imageEnhancementDetectionSequence) {
        state.imageEnhancementLastDetectionSignature = "";
        state.imageEnhancementIntegration = normalizeImageEnhancementIntegrationStatus({});
        syncImageEnhancementIntegrationUi();
        setImageEnhancementModalFeedback(
          error instanceof Error ? error.message : "Unable to detect the AI provider.",
        );
      }
    } finally {
      if (requestSequence === state.imageEnhancementDetectionSequence) {
        state.imageEnhancementDetecting = false;
        syncImageEnhancementIntegrationUi();
      }
    }
  }

  async function saveImageEnhancementIntegration() {
    if (
      state.imageEnhancementSaving
      || state.imageEnhancementLaunching
      || state.imageEnhancementSyncingModels
    ) {
      return;
    }
    const currentStatus = normalizeImageEnhancementIntegrationStatus(
      state.imageEnhancementIntegration,
    );
    const chatModel = String(elements.imageEnhancementChatModelSelect?.value || "").trim();
    const imageModel = String(elements.imageEnhancementImageModelSelect?.value || "").trim();
    const capabilities = {};
    for (const toggle of elements.imageEnhancementCapabilityToggles) {
      if (toggle instanceof HTMLInputElement) {
        const key = toggle.dataset.aiCapabilityToggle;
        capabilities[key] = Boolean(
          toggle.checked && !toggle.disabled && !currentStatus.claimedByOthers?.[key],
        );
      }
    }
    setImageEnhancementFeedback("");
    if (!currentStatus.configured) {
      setImageEnhancementFeedback("Sync provider models before saving integration settings.");
      elements.imageEnhancementSyncModelsButton?.focus();
      return;
    }
    if ((capabilities.chatbot || capabilities.autoReply) && !chatModel) {
      setImageEnhancementFeedback("Select a chat model for chatbot and automatic replies.");
      focusAiModelDropdown(elements.imageEnhancementChatModelSelect);
      return;
    }
    if (capabilities.imageEnhancement && !imageModel) {
      setImageEnhancementFeedback("Select an image model for photo enhancement.");
      focusAiModelDropdown(elements.imageEnhancementImageModelSelect);
      return;
    }

    state.imageEnhancementSaving = true;
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration", {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: currentStatus.id || state.imageEnhancementEditingId,
          chatModel,
          imageModel,
          capabilities,
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to save the AI integration.");
      }
      applyAiIntegrationCollection(data, {
        persist: true,
        selectedId: data.integration?.id || currentStatus.id,
      });
      state.imageEnhancementSettingsDirty = false;
      state.imageEnhancementLastDetectionSignature = "";
      state.imageEnhancementStatusLoaded = true;
      syncImageEnhancementIntegrationUi();
      void showSuccessValidationModal(
        "AI Integration Saved",
        data.message || "The shared AI integration has been saved.",
      );
    } catch (error) {
      setImageEnhancementFeedback(
        error instanceof Error ? error.message : "Unable to save the AI integration.",
      );
    } finally {
      state.imageEnhancementSaving = false;
      syncImageEnhancementIntegrationUi();
    }
  }

  async function toggleImageEnhancementLaunch() {
    if (
      state.imageEnhancementSaving
      || state.imageEnhancementLaunching
      || state.imageEnhancementSyncingModels
    ) {
      return;
    }
    const currentStatus = normalizeImageEnhancementIntegrationStatus(
      state.imageEnhancementIntegration,
    );
    if (state.imageEnhancementSettingsDirty) {
      setImageEnhancementFeedback("Save the model and feature changes before changing the launch status.");
      elements.imageEnhancementSaveButton?.focus();
      return;
    }
    if (!currentStatus.configured) {
      setImageEnhancementFeedback("Sync provider models before launching the service.");
      elements.imageEnhancementSyncModelsButton?.focus();
      return;
    }

    state.imageEnhancementLaunching = true;
    setImageEnhancementFeedback("");
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration/launch", {
        method: "POST",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({
          id: currentStatus.id || state.imageEnhancementEditingId,
          launched: !currentStatus.launched,
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to change the AI API status.");
      }
      applyAiIntegrationCollection(data, {
        persist: true,
        selectedId: currentStatus.id || state.imageEnhancementEditingId,
      });
      state.imageEnhancementSettingsDirty = false;
      state.imageEnhancementStatusLoaded = true;
      await loadImageEnhancementIntegrationStatus();
      syncImageEnhancementIntegrationUi();
      void showSuccessValidationModal(
        data.launched ? "AI Integration Launched" : "AI Integration Stopped",
        data.message || (data.launched
          ? "The enabled AI services are now available."
          : "The shared AI integration has been stopped."),
      );
    } catch (error) {
      setImageEnhancementFeedback(
        error instanceof Error ? error.message : "Unable to change the AI API status.",
      );
    } finally {
      state.imageEnhancementLaunching = false;
      syncImageEnhancementIntegrationUi();
    }
  }

