  async function connectImageEnhancementIntegrationFromModal() {
    if (
      state.imageEnhancementLoading
      || state.imageEnhancementSaving
      || state.imageEnhancementLaunching
    ) {
      return;
    }
    const apiKey = String(elements.imageEnhancementApiKeyInput?.value || "").trim();
    if (!apiKey) {
      setImageEnhancementModalFeedback("Enter an AI provider API key.");
      elements.imageEnhancementApiKeyInput?.focus();
      return;
    }

    window.clearTimeout(imageEnhancementAutoDetectTimer);
    state.imageEnhancementDetectionSequence += 1;
    state.imageEnhancementDetecting = false;
    state.imageEnhancementLastDetectionSignature = "";
    state.imageEnhancementSaving = true;
    setImageEnhancementModalFeedback(
      "Detecting the provider and loading compatible models...",
      "info",
    );
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration", {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(
          state.imageEnhancementApiKeyMode === "replace" && state.imageEnhancementEditingId
            ? { id: state.imageEnhancementEditingId, apiKey }
            : { apiKey },
        ),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to connect the AI provider.");
      }
      applyAiIntegrationCollection(data, {
        persist: true,
        selectedId: data.integration?.id || state.imageEnhancementEditingId,
      });
      state.imageEnhancementApiKeyMode = "add";
      state.imageEnhancementSettingsDirty = false;
      state.imageEnhancementStatusLoaded = true;
      setImageEnhancementTableFeedback("");
      syncImageEnhancementIntegrationUi();
      setImageEnhancementApiKeyModalOpen(false, { restoreFocus: false });
      void showSuccessValidationModal(
        "AI Provider Connected",
        data.message || `${state.imageEnhancementIntegration.providerLabel || "AI provider"} is now listed in AI Integrations.`,
      );
    } catch (error) {
      setImageEnhancementModalFeedback(
        error instanceof Error ? error.message : "Unable to connect the AI provider.",
      );
    } finally {
      state.imageEnhancementSaving = false;
      syncImageEnhancementIntegrationUi();
    }
  }

  async function deleteImageEnhancementIntegration(status) {
    const target = normalizeImageEnhancementIntegrationStatus(status);
    if (!target.id) {
      return;
    }
    const confirmed = await confirmDeleteValidationModal(
      "Delete AI integration",
      `Remove ${target.providerLabel || "this AI provider"} from AI Integrations? Its connected features will become available to another provider.`,
    );
    if (!confirmed) {
      return;
    }
    state.imageEnhancementSaving = true;
    setImageEnhancementBusyState();
    try {
      const response = await fetch("/api/super-admin/ai-integration", {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({ id: target.id, remove: true }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to delete the AI integration.");
      }
      if (state.imageEnhancementEditingId === target.id) {
        closeImageEnhancementDrawer({ restoreFocus: false });
        state.imageEnhancementEditingId = "";
      }
      applyAiIntegrationCollection(data, { persist: true });
      state.imageEnhancementSettingsDirty = false;
      setImageEnhancementTableFeedback("");
      syncImageEnhancementIntegrationUi();
      void showSuccessValidationModal(
        "AI Integration Removed",
        data.message || `${target.providerLabel || "The AI provider"} has been removed.`,
      );
    } catch (error) {
      setImageEnhancementTableFeedback(
        error instanceof Error ? error.message : "Unable to delete the AI integration.",
      );
    } finally {
      state.imageEnhancementSaving = false;
      syncImageEnhancementIntegrationUi();
    }
  }

