  function getVisibleSuperAdminActivities() {
    const entries = Array.isArray(state.saActivities) ? state.saActivities : [];
    if (state.saActivityCategory === "all") {
      return entries;
    }
    return entries.filter(
      (entry) => String(entry?.category || "").trim().toLowerCase() === state.saActivityCategory,
    );
  }

  function formatSuperAdminActivityTime(value) {
    const timestamp = String(value || "").trim();
    const parsed = Date.parse(timestamp);
    if (Number.isNaN(parsed)) {
      return "Recently";
    }
    const elapsedSeconds = Math.max(0, Math.floor((Date.now() - parsed) / 1000));
    if (elapsedSeconds < 3600) {
      return `${numberText(Math.max(1, Math.floor(elapsedSeconds / 60)))}m ago`;
    }
    if (elapsedSeconds < 86400) {
      return `${numberText(Math.floor(elapsedSeconds / 3600))}h ago`;
    }
    const days = Math.floor(elapsedSeconds / 86400);
    if (days < 30) {
      return `${numberText(days)} day${days === 1 ? "" : "s"} ago`;
    }
    return formatRelativeTime(timestamp);
  }

  function createSuperAdminActivityItem(entry) {
    const item = document.createElement("article");
    const category = String(entry?.category || "settings").trim().toLowerCase() || "settings";
    const title = String(entry?.title || "Super Admin activity").trim();
    const description = String(entry?.description || "").trim();
    item.className = `activity-item activity-item--notification activity-item--clickable super-admin-notification-activity sa-notif-card sa-activity-card sa-notif-card--${category}`;
    item.tabIndex = 0;
    item.setAttribute("role", "link");
    item.setAttribute("aria-label", title);
    item.innerHTML = `
      <span class="activity-item__avatar activity-item__avatar--admin sa-notif-card__avatar is-switch-logo has-image" aria-hidden="true">
        <span class="activity-item__avatar-icon"></span>
      </span>
      <div class="activity-item__body sa-notif-card__body">
        <div class="sa-notif-card__meta">
          <strong class="sa-notif-card__title">${escapeHtml(title)}</strong>
          <span class="activity-item__timestamp sa-notif-card__time">${escapeHtml(formatSuperAdminActivityTime(entry?.createdAt))}</span>
        </div>
        <p class="sa-notif-card__message">${escapeHtml(description || "System management action recorded.")}</p>
      </div>
    `;
    applySwitchLogoAvatar(item);
    const openActivity = () => {
      setActivityPanelOpen(false);
      void openSuperAdminNotificationLanding(entry);
    };
    item.addEventListener("click", openActivity);
    item.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") {
        return;
      }
      event.preventDefault();
      openActivity();
    });
    return item;
  }

