  async function loadSuperAdminActivity({ force = false } = {}) {
    if (state.saActivitiesLoading) {
      return;
    }
    const fresh =
      state.saActivitiesLoadedAt > 0 &&
      Date.now() - state.saActivitiesLoadedAt < 15000;
    if (!force && fresh) {
      return;
    }
    state.saActivitiesLoading = true;
    state.saActivitiesError = "";
    renderActivityPanel();
    try {
      const response = await fetch("/api/super-admin/activity?limit=100", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to load activity.");
      }
      state.saActivities = Array.isArray(data.activities) ? data.activities : [];
      state.saActivitiesLoadedAt = Date.now();
    } catch (error) {
      state.saActivitiesError = error instanceof Error ? error.message : "Unable to load activity.";
    } finally {
      state.saActivitiesLoading = false;
      renderActivityPanel();
    }
  }

