  elements.reportWarnModalDialog?.addEventListener("keydown", (event) => {
    if (event.key !== "Tab") {
      return;
    }
    const focusable = Array.from(
      elements.reportWarnModalDialog.querySelectorAll(
        'button:not(:disabled):not([tabindex="-1"]), textarea:not(:disabled), input:not(:disabled), select:not(:disabled), [href], [tabindex]:not([tabindex="-1"])',
      ),
    ).filter((element) => (
      element instanceof HTMLElement
      && !element.hidden
      && !element.closest("[hidden]")
      && element.getClientRects().length > 0
    ));
    if (!focusable.length) {
      event.preventDefault();
      elements.reportWarnModalDialog.focus();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  });

  for (const option of elements.reportWarnActionOptions) {
    option.addEventListener("click", () => {
      if (option.disabled || option.getAttribute("aria-disabled") === "true") {
        return;
      }
      setReportWarnModalAction(option.dataset.superAdminReportWarnAction);
    });
    option.addEventListener("keydown", (event) => {
      if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) {
        return;
      }
      const enabledOptions = elements.reportWarnActionOptions.filter(
        (candidate) => !candidate.disabled && candidate.getAttribute("aria-disabled") !== "true",
      );
      if (!enabledOptions.length) {
        return;
      }
      event.preventDefault();
      const currentIndex = Math.max(0, enabledOptions.indexOf(option));
      const nextIndex = event.key === "Home"
        ? 0
        : event.key === "End"
          ? enabledOptions.length - 1
          : (currentIndex + (["ArrowRight", "ArrowDown"].includes(event.key) ? 1 : -1) + enabledOptions.length)
            % enabledOptions.length;
      const nextOption = enabledOptions[nextIndex];
      nextOption.focus();
      setReportWarnModalAction(nextOption.dataset.superAdminReportWarnAction);
    });
  }

